function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) { return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] }; }
function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews) { return { id, skillId, stem, options, answerIndex, reasons, difficulty, cognitiveProcess: ["呼吸系統判讀", "證據推理"], representationType: "文字與資料判讀", misconceptionTargets: [], reviews, assets: [] }; }
function stimulus(id, skillId, type, content, accessibility, questions) { return { id, skillId, type, content, accessibility, questions, assets: [] }; }

const lectures = [];
const questions = [];
const stimuli = [];

lectures.push(lecture("BIO_R4_L_S057", "BIO_R4_S057",
  ["依吸入空氣方向辨識人體呼吸道主要構造。", "區分空氣通過的呼吸道與肺泡氣體交換位置。"],
  [
    { id: "BIO_R4_L_S057_SEC_01", title: "空氣由鼻腔進入", content: "正常吸氣時空氣多由鼻腔進入，鼻腔可使空氣較溫暖、濕潤並攔截部分顆粒。用口呼吸也可讓空氣進入，但會少掉部分鼻腔處理作用。" },
    { id: "BIO_R4_L_S057_SEC_02", title: "咽喉連接氣管", content: "空氣由鼻腔經咽、喉進入氣管。咽同時與消化、呼吸路徑相關，吞嚥時會有構造協助避免食物進入氣管；不能把食道排進正常空氣路徑。" },
    { id: "BIO_R4_L_S057_SEC_03", title: "氣管分成支氣管", content: "氣管向下分成左右支氣管，分別進入兩側肺，再分支成更細的管道。呼吸道的功能是運送空氣，真正大量氣體交換主要發生在末端肺泡。" },
    { id: "BIO_R4_L_S057_SEC_04", title: "肺泡是路徑末端", content: "肺泡位於肺內細小呼吸道末端，吸入氣體最後到達肺泡，氧才有機會進入周圍微血管。呼出時方向相反，氣體由肺泡沿支氣管與氣管離開。" },
  ],
  [
    { id: "BIO_R4_L_S057_EX_01", prompt: "空氣通過氣管後，下一個主要構造是哪裡？", steps: ["依吸氣方向定位氣管。", "接續氣管分叉後的左右管道。"], answer: "支氣管", why: "氣管在胸腔分成左右支氣管並進入肺，因此正常空氣不會由氣管直接跳到食道或胃。" },
    { id: "BIO_R4_L_S057_EX_02", prompt: "食道是否屬於吸入空氣的正常路徑？", steps: ["區分咽之後的氣管與食道。", "確認空氣應進入呼吸系統。"], answer: "不屬於", why: "食道把食團送往胃，吸入空氣應由喉進入氣管；若異物進入氣管會引發咳嗽等保護反應。" },
    { id: "BIO_R4_L_S057_EX_03", prompt: "氣體交換後的二氧化碳由肺泡排出，方向如何？", steps: ["從肺泡作為呼吸道末端開始。", "依吸氣路徑反向排列至鼻腔。"], answer: "肺泡到支氣管、氣管，再由鼻腔或口腔離開", why: "呼氣時空氣沿吸氣路徑大致反向流動，肺泡中的氣體經細支氣管、支氣管與氣管排出體外。" },
  ],
  [
    { belief: "吸入空氣會依序通過食道和胃。", whyWrong: "食道與胃屬消化道，正常空氣由喉進入氣管與支氣管。", correction: "在咽之後選氣管路徑，不把食團通道混入空氣路徑。" },
    { belief: "氣管直接連接所有肺泡，中間沒有分支。", whyWrong: "氣管先分成支氣管，再逐級形成更細管道到達肺泡。", correction: "依管徑由大到小排列氣管、支氣管、細支氣管與肺泡。" },
    { belief: "鼻腔只是外觀構造，與呼吸無關。", whyWrong: "鼻腔是常見空氣入口，並能溫暖、濕潤和過濾部分顆粒。", correction: "把鼻腔列為呼吸道前段，同時理解其初步處理空氣功能。" },
    { belief: "空氣到達支氣管就完成氣體交換。", whyWrong: "支氣管主要運送空氣，大量交換需到肺泡與微血管界面。", correction: "區分呼吸道運送段與肺泡交換段，不以管道名稱代替交換位置。" },
  ],
  [
    { prompt: "氣管之後空氣先進入哪裡？", answer: "支氣管", reason: "氣管在胸腔分叉成左右支氣管，分別把空氣送入兩側肺。" },
    { prompt: "正常吸氣路徑是否包含食道？", answer: "不包含", reason: "食道運送食物到胃，吸入空氣由喉進入氣管而非食道。" },
    { prompt: "氣體交換主要在呼吸道哪個末端構造？", answer: "肺泡", reason: "肺泡緊鄰微血管並具有薄壁，是大量氧與二氧化碳交換場所。" },
  ],
));

questions.push(
  question("BIO_R4_Q_057_01", "BIO_R4_S057", "foundation", "正常吸氣時，空氣最常先由哪個構造進入？", ["鼻腔", "胃部", "小腸", "膀胱"], 0, ["鼻腔是正常吸氣常用入口並可處理空氣。", "胃接收食物而不是吸入氣體。", "小腸位於消化道後段。", "膀胱只暫時儲存尿液。"], ["題目問空氣入口，鼻腔位於呼吸道最前段。", "其餘器官分屬消化或泌尿系統，不與外界吸氣直接相通。"]),
  question("BIO_R4_Q_057_02", "BIO_R4_S057", "foundation", "空氣通過喉之後，會先進入哪一個主要構造？", ["食道", "氣管", "胃部", "大腸"], 1, ["食道是食團通往胃的管道。", "喉向下連接氣管，供空氣通過。", "胃不直接連接呼吸道。", "大腸更不在空氣路徑中。"], ["由鼻腔、咽、喉向後，下一段是氣管。", "「氣管」符合相鄰位置，其他選項全屬消化道而非呼吸道。"]),
  question("BIO_R4_Q_057_03", "BIO_R4_S057", "foundation", "氣管向下分叉後形成哪一對主要管道？", ["輸尿管", "食道", "支氣管", "膽管"], 2, ["輸尿管把尿液由腎送到膀胱。", "食道不由氣管分叉形成。", "左右支氣管由氣管分出並進入肺。", "膽管運送膽汁到小腸。"], ["氣管在胸腔分成左右支氣管，這是呼吸道的正常分支。", "另外三種管道位於泌尿或消化系統，來源與功能皆不同。"]),
  question("BIO_R4_Q_057_04", "BIO_R4_S057", "standard", "下列哪個順序最符合吸入空氣的方向？", ["胃→食道→咽", "肺泡→支氣管→氣管", "大腸→小腸→胃", "鼻腔→咽→喉→氣管"], 3, ["此為部分消化道且方向倒轉。", "此順序較接近呼氣方向。", "大腸小腸胃不是呼吸道。", "此項正確排列呼吸道前段。"], ["吸氣由外界鼻腔進入，依序經咽、喉到氣管。", "「鼻腔→咽→喉→氣管」是唯一器官皆屬呼吸道且方向由外向內的路徑。"]),
  question("BIO_R4_Q_057_05", "BIO_R4_S057", "standard", "下列哪個構造不屬於正常空氣通過路徑？", ["食道", "鼻腔", "氣管", "支氣管"], 0, ["食道屬消化道，正常空氣不由其中通過。", "鼻腔是常見的吸氣入口。", "氣管把空氣送向胸腔。", "支氣管再把空氣送入肺內。"], ["題目要求排除呼吸道，食道負責食物運送到胃。", "鼻腔、氣管與支氣管彼此構成吸入空氣的連續路徑。"]),
  question("BIO_R4_Q_057_06", "BIO_R4_S057", "standard", "空氣經支氣管進入肺後，最後到達哪個交換構造？", ["腎小球", "肺泡", "小腸絨毛", "胃腺"], 1, ["腎小球過濾血液形成尿液。", "肺泡位於呼吸道末端並與微血管相鄰。", "小腸絨毛負責養分吸收。", "胃腺分泌胃液而不換氣。"], ["支氣管在肺內逐級分支，末端連接大量肺泡。", "「肺泡」符合位置與氣體交換功能，其餘構造屬其他器官系統。"]),
  question("BIO_R4_Q_057_07", "BIO_R4_S057", "standard", "呼氣時二氧化碳由肺泡離開，方向最先經過哪裡？", ["小腸", "食道", "肺內細小呼吸道", "膀胱"], 2, ["小腸運送與消化食物。", "食道也不屬呼吸道。", "肺泡氣體先進入相連的細小呼吸道。", "膀胱是泌尿系統儲尿器官。"], ["呼氣大致沿吸氣路徑反向，肺泡先接肺內細小呼吸道。", "「肺內細小呼吸道」是唯一與肺泡直接相連的呼吸構造。"]),
  question("BIO_R4_Q_057_08", "BIO_R4_S057", "advanced", "異物卡在氣管分叉處，最直接妨礙空氣進入哪裡？", ["胃與小腸", "腎與膀胱", "肝與膽囊", "左右支氣管與肺"], 3, ["胃小腸接收食物而非氣管空氣。", "泌尿器官也不接氣管分叉。", "肝膽不屬呼吸道分支。", "氣管分叉正連接左右支氣管。"], ["由氣管相鄰關係推論，分叉阻塞會直接影響兩側支氣管進氣。", "「左右支氣管與肺」位於阻塞後方，其他配對沒有空氣管道連接。"]),
  question("BIO_R4_Q_057_09", "BIO_R4_S057", "advanced", "鼻腔嚴重阻塞而改用口呼吸，最可能少掉鼻腔哪項作用？", ["溫暖、濕潤並攔截部分顆粒", "把食物分解成葡萄糖", "形成尿液並儲存", "製造膽汁並乳化脂質"], 0, ["鼻腔可初步調節與過濾吸入空氣。", "食物化學分解不由鼻腔完成。", "尿液形成與儲存屬泌尿系統。", "膽汁由肝製造並作用於小腸。"], ["改用口呼吸仍可進氣，但繞過鼻腔的空氣處理功能。", "「溫暖、濕潤並攔截部分顆粒」符合鼻腔構造位置，其餘皆屬消化或泌尿功能。"]),
  question("BIO_R4_Q_057_10", "BIO_R4_S057", "advanced", "咽為呼吸與消化路徑交會處，何者是正常情況？", ["食物經氣管到胃", "空氣進氣管，食團進食道", "空氣經食道到肺", "食團經支氣管到小腸"], 1, ["氣管不連接胃且食物誤入會嗆咳。", "兩種物質各進入正確後續管道。", "食道通往胃而不是肺。", "支氣管只運送空氣進肺。"], ["咽後方的路徑需要分流，空氣走氣管，食團走食道。", "「空氣進氣管，食團進食道」正確區分兩條管道，其他選項都把目的地交叉錯配。"]),
  question("BIO_R4_Q_057_11", "BIO_R4_S057", "transfer", "醫師由鼻腔放入細管觀察支氣管，最合理的通過順序為何？", ["鼻腔→胃→支氣管", "鼻腔→食道→肺泡", "鼻腔→咽→喉→氣管→支氣管", "鼻腔→小腸→氣管"], 2, ["胃與支氣管沒有直接管腔連接。", "食道不會通往肺泡。", "此項依呼吸道前後順序排列。", "小腸也不在鼻腔到氣管的路徑。"], ["從鼻腔向內觀察支氣管，器械需沿正常呼吸道前段前進。", "「鼻腔→咽→喉→氣管→支氣管」完整且連續，其他選項混入消化道器官。"]),
  question("BIO_R4_Q_057_12", "BIO_R4_S057", "transfer", "若左右支氣管都阻塞但氣管通暢，最合理的影響是什麼？", ["食物無法進胃", "尿液無法進膀胱", "膽汁無法進小腸", "空氣難以由氣管進入兩側肺"], 3, ["食物走食道而不經支氣管。", "尿液由輸尿管進入膀胱。", "膽汁經膽管進小腸。", "支氣管是氣管通往肺的必經分支。"], ["阻塞位置在氣管之後、肺之前，因此直接妨礙兩側肺進氣。", "「空氣難以由氣管進入兩側肺」符合管道連接，其他選項是不同系統的運輸路徑。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S057", "BIO_R4_S057", "airflow-trace",
  { title: "吸入微粒定位紀錄", text: "研究模型以無害標記微粒模擬吸入空氣，依時間記錄微粒位置。微粒只沿呼吸道管腔前進，不進入食道或消化器官；到達肺泡後停止追蹤。", note: "時間只代表出現先後，不用來比較各段氣流速度。" },
  { summary: "表格依時間列出微粒在鼻腔、咽、氣管、支氣管與肺泡的位置。", colorIndependent: true, dataFallback: { columns: ["時間", "位置"], rows: [["0秒", "鼻腔"], ["1秒", "咽"], ["2秒", "氣管"], ["3秒", "支氣管"], ["5秒", "肺泡"]] } },
  [
    question("BIO_R4_SQ_057_01", "BIO_R4_S057", "standard", "微粒離開氣管後，依紀錄先出現在哪裡？", ["支氣管", "食道", "胃部", "小腸"], 0, ["3秒位置是支氣管，直接接在氣管後。", "材料明示微粒不進入食道。", "胃不屬於呼吸道。", "小腸也不是吸入空氣路徑。"], ["依時間資料，氣管2秒後的下一筆為支氣管3秒。", "此先後也符合氣管向下分成左右支氣管的構造。"]),
    question("BIO_R4_SQ_057_02", "BIO_R4_S057", "advanced", "由紀錄可判斷氣體交換位置最可能是哪裡？", ["咽部", "肺泡", "氣管", "鼻腔"], 1, ["咽是空氣通道交會處而非主要交換面。", "肺泡是末端且與微血管相鄰。", "氣管主要負責運送空氣。", "鼻腔主要處理剛吸入的空氣。"], ["微粒最終到達肺泡，而課程中肺泡是主要氣體交換構造。", "「肺泡」同時符合路徑末端與功能，其他構造以運送或處理為主。"]),
    question("BIO_R4_SQ_057_03", "BIO_R4_S057", "transfer", "若支氣管完全阻塞，表中哪筆後續紀錄最可能消失？", ["0秒鼻腔", "1秒咽", "5秒肺泡", "2秒氣管"], 2, ["阻塞在更後方，不妨礙微粒先到鼻腔。", "微粒也可先通過咽再到阻塞處。", "無法通過支氣管就難以到達肺泡。", "氣管位於支氣管之前仍可能出現微粒。"], ["阻塞會影響位置後方而非前方，肺泡位於支氣管之後。", "「5秒肺泡」是唯一需要先通過阻塞處才可出現的紀錄。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S058", "BIO_R4_S058",
  ["說明肺泡構造如何提高氣體交換效率。", "由面積、厚度、濕潤表面與微血管分布推論交換影響。"],
  [
    { id: "BIO_R4_L_S058_SEC_01", title: "大量肺泡提供大面積", content: "肺內有數量很多的小肺泡，總表面積遠大於少數大囊。大面積提供更多空氣與血液相鄰的交換位置，使同一時間可有較多氣體分子通過。" },
    { id: "BIO_R4_L_S058_SEC_02", title: "薄壁縮短交換距離", content: "肺泡壁與周圍微血管壁都很薄，使氧和二氧化碳穿越的距離短。若壁因病變增厚，即使肺泡內仍有空氣，交換速率也可能下降。" },
    { id: "BIO_R4_L_S058_SEC_03", title: "濕潤表面與氣體溶解", content: "肺泡內表面保持濕潤，氧與二氧化碳可先溶解再通過薄壁。濕潤不等於肺泡充滿大量液體；過多液體反而會增加交換距離並妨礙換氣。" },
    { id: "BIO_R4_L_S058_SEC_04", title: "微血管與濃度差", content: "肺泡外密布微血管，血流帶走進入血液的氧並帶來二氧化碳；呼吸運動持續更新肺泡氣體。兩者共同維持濃度差，使交換能持續進行。" },
  ],
  [
    { id: "BIO_R4_L_S058_EX_01", prompt: "肺泡數量多比單一大囊有何主要優勢？", steps: ["比較相同體積下表面分割程度。", "連結總面積與同時交換位置。"], answer: "提供較大的總交換面積", why: "許多小囊能增加空氣與微血管接觸的總表面，使更多氧與二氧化碳可同時進行交換。" },
    { id: "BIO_R4_L_S058_EX_02", prompt: "肺泡壁變厚時，為何交換效率可能下降？", steps: ["確認氣體需穿過肺泡壁與微血管壁。", "比較壁厚與擴散距離。"], answer: "氣體移動距離增加", why: "氧與二氧化碳要跨越較厚屏障，移動路徑變長，因此在相同時間內通過的量可能減少。" },
    { id: "BIO_R4_L_S058_EX_03", prompt: "肺泡外微血管血流停止，交換為何難以持續？", steps: ["辨認血流原本會帶走氧並帶來二氧化碳。", "判斷局部濃度差會如何改變。"], answer: "濃度差逐漸縮小", why: "血液不再更新時，肺泡與鄰近血液的氧、二氧化碳差異會減少，使氣體淨移動的驅動力下降。" },
  ],
  [
    { belief: "肺泡越大顆，總交換面積一定越大。", whyWrong: "相同體積分成許多小囊通常可得到更大的總表面積。", correction: "比較總面積而非單顆大小，理解大量小肺泡的優勢。" },
    { belief: "肺泡壁越厚越能加快交換。", whyWrong: "厚壁會增加氣體穿越距離，通常降低單位時間交換量。", correction: "薄壁與薄微血管壁共同縮短氧和二氧化碳移動路徑。" },
    { belief: "肺泡濕潤表示應裝滿液體。", whyWrong: "薄層水分有助氣體溶解，過多液體卻會占空間並增加距離。", correction: "區分表面薄層濕潤與肺泡腔被大量液體占據。" },
    { belief: "只要肺泡存在就不需要血流。", whyWrong: "微血管血流負責運走氧、帶來二氧化碳並維持濃度差。", correction: "把肺泡換氣與肺部血流視為氣體交換共同必要條件。" },
  ],
  [
    { prompt: "大量小肺泡最直接增加什麼？", answer: "交換表面積", reason: "許多小囊提供更多空氣與微血管相鄰的表面位置。" },
    { prompt: "肺泡壁薄有何交換優勢？", answer: "縮短氣體移動距離", reason: "氧和二氧化碳穿過較薄屏障時，交換路徑較短。" },
    { prompt: "肺泡外微血管為何重要？", answer: "運送氣體並維持濃度差", reason: "血流帶走氧並帶來二氧化碳，使淨交換能持續進行。" },
  ],
));

questions.push(
  question("BIO_R4_Q_058_01", "BIO_R4_S058", "foundation", "肺內有大量小肺泡，最直接增加哪一項？", ["氣體交換總面積", "食物消化時間", "尿液儲存空間", "牙齒咀嚼力量"], 0, ["大量小囊提供較大的總交換表面。", "肺泡不參與食物化學消化。", "尿液儲存在膀胱而非肺泡。", "咀嚼力量也不由肺泡決定。"], ["肺泡數量多的構造效益是增加空氣與微血管接觸面。", "「氣體交換總面積」符合肺泡功能，其他選項分屬消化、泌尿與口腔。"]),
  question("BIO_R4_Q_058_02", "BIO_R4_S058", "foundation", "肺泡壁很薄，對氣體交換最直接的幫助為何？", ["增加食物表面積", "縮短氣體移動距離", "製造更多血紅素", "形成更多尿液"], 1, ["食物表面積與肺泡壁無關。", "薄壁使氧與二氧化碳通過路徑較短。", "血紅素由血球相關過程形成。", "尿液由腎臟形成而非肺泡。"], ["氣體需由肺泡腔跨壁到微血管，薄壁可縮短此距離。", "「縮短氣體移動距離」是直接構造功能關係，「增加食物表面積」、「製造更多血紅素」、「形成更多尿液」位於其他系統。"]),
  question("BIO_R4_Q_058_03", "BIO_R4_S058", "foundation", "肺泡外密布微血管，主要有什麼作用？", ["切碎食物", "運送尿液", "接收氧並帶來二氧化碳", "分泌膽汁"], 2, ["切碎食物由牙齒負責。", "尿液經輸尿管運送。", "微血管與肺泡進行雙向氣體交換。", "膽汁由肝臟製造。"], ["肺泡微血管把氧送入循環並把二氧化碳帶到肺泡。", "「接收氧並帶來二氧化碳」符合位置與血流功能，其他作用不在肺部發生。"]),
  question("BIO_R4_Q_058_04", "BIO_R4_S058", "standard", "下列哪組肺泡特徵與功能配對正確？", ["厚壁－縮短距離", "少數大囊－增加總面積", "無血管－維持交換", "薄壁且多微血管－利於氣體交換"], 3, ["厚壁會增加而不是縮短距離。", "少數大囊的總面積通常較小。", "缺少血流不利維持濃度差。", "兩項特徵共同提高交換效率。"], ["薄壁減少距離，密集微血管負責運輸並維持濃度差。", "「薄壁且多微血管－利於氣體交換」的構造與功能方向一致，其他配對皆相反。"]),
  question("BIO_R4_Q_058_05", "BIO_R4_S058", "standard", "肺泡壁因病變增厚，最可能直接造成什麼？", ["氣體交換效率下降", "小腸吸收面積增加", "食道推送加快", "膽汁分泌增多"], 0, ["屏障增厚使氣體穿越距離增加。", "肺泡病變不會增加小腸絨毛。", "食道運動也不由肺泡壁控制。", "膽汁分泌與肺泡厚度無直接關係。"], ["肺泡壁是氧與二氧化碳必須通過的屏障，變厚會妨礙交換。", "「氣體交換效率下降」是局部直接影響，其他項目跨到無關消化功能。"]),
  question("BIO_R4_Q_058_06", "BIO_R4_S058", "standard", "肺泡表面薄層水分的主要意義是什麼？", ["直接製造氧氣", "讓氣體先溶解以利交換", "把肺泡變成胃", "完全阻止二氧化碳移動"], 1, ["人體肺泡不會直接製造氧氣。", "氣體溶於薄層水分後可跨越肺泡壁。", "濕潤表面不會改變器官種類。", "二氧化碳也能由血液移入肺泡。"], ["適度濕潤提供氣體溶解的界面，有利於跨膜移動。", "「讓氣體先溶解以利交換」區分薄層濕潤與大量積液，其他敘述皆不正確。"]),
  question("BIO_R4_Q_058_07", "BIO_R4_S058", "standard", "若肺泡外血流停止，交換逐漸下降的主要原因為何？", ["肺泡立即變成實心", "空氣全部變成水", "肺泡與血液的濃度差難以維持", "鼻腔完全消失"], 2, ["血流停止不會讓肺泡立即實心化。", "氣體也不會因此全部轉成水。", "無法運走與帶來氣體會縮小濃度差。", "鼻腔構造不因肺部血流停止消失。"], ["微血管血流更新血液中的氣體含量，是維持濃度差的重要條件。", "「肺泡與血液的濃度差難以維持」解釋交換逐漸下降，其他選項缺乏物質與構造依據。"]),
  question("BIO_R4_Q_058_08", "BIO_R4_S058", "advanced", "相同體積下，多個小囊比單一大囊交換較快，最合理原因為何？", ["小囊內沒有氣體", "大囊壁一定更薄", "小囊會製造微血管", "多個小囊的總表面積較大"], 3, ["小囊仍需含空氣才能交換。", "題幹沒有提供壁厚差異。", "肺泡本身不會製造血管。", "分割成小囊可增加總表面。"], ["控制總體積後，最能解釋交換差異的是表面積與體積比增加。", "「多個小囊的總表面積較大」符合幾何與肺泡功能，其他選項不是資料所給條件。"]),
  question("BIO_R4_Q_058_09", "BIO_R4_S058", "advanced", "肺泡積液使交換下降，最合理的機制為何？", ["液體增加氣體通過距離並占據換氣空間", "液體直接把氧變成蛋白質", "液體使肺泡數量無限增加", "液體替代全部微血管"], 0, ["過多液體造成更長路徑並減少有效含氣空間。", "氧不會因積液轉變成蛋白質。", "積液不會使肺泡數量增加。", "液體也不能取代血管運輸。"], ["適度濕潤與大量積液不同，後者增加交換障礙並占據肺泡。", "「液體增加氣體通過距離並占據換氣空間」同時解釋距離與換氣空間，其他選項違反生理機制。"]),
  question("BIO_R4_Q_058_10", "BIO_R4_S058", "advanced", "哪項資料最能證明肺泡微血管有助維持氧濃度差？", ["肺泡數量很多", "血流越快時肺泡旁低氧血更新越快", "鼻腔具有鼻毛", "氣管有軟骨支撐"], 1, ["肺泡數量只支持總面積優勢。", "血流更新直接影響交換界面的氧差。", "鼻毛主要攔截較大顆粒。", "氣管軟骨主要維持管道通暢。"], ["要證明血管維持濃度差，需比較血流更新與局部氧狀態。", "「血流越快時肺泡旁低氧血更新越快」提供直接關係，其他特徵雖與呼吸相關但回答不同問題。"]),
  question("BIO_R4_Q_058_11", "BIO_R4_S058", "transfer", "人工氣體交換膜若要模仿肺泡，哪種設計最佳？", ["厚膜且無流動液體", "小面積乾燥實心塊", "大面積薄濕膜且另一側有流動液體", "只增加外殼重量"], 2, ["厚膜與停滯液體都不利交換。", "小面積乾燥實心塊缺少關鍵條件。", "此設計模仿面積、距離、濕潤與血流。", "外殼重量不能提高氣體跨膜效率。"], ["肺泡交換優勢來自多項構造共同作用，人工膜也需同時保留。", "「大面積薄濕膜且另一側有流動液體」包含大面積、薄濕界面與流動運輸，是最完整設計。"]),
  question("BIO_R4_Q_058_12", "BIO_R4_S058", "transfer", "若肺泡數量減少但每個肺泡壁仍薄，最可能出現什麼？", ["交換距離必定縮短為零", "血液不再含任何水", "胃內消化完全停止", "總交換面積減少而影響氧進入血液"], 3, ["壁薄不表示距離等於零。", "肺泡數量不會使血液失去全部水。", "胃消化也非肺泡數量的直接結果。", "肺泡減少會降低可用交換總面積。"], ["每個肺泡條件保留，但數量減少會使整體表面積下降。", "「總交換面積減少而影響氧進入血液」是直接構造功能推論，沒有誇大為其他系統停止。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S058", "BIO_R4_S058", "membrane-model",
  { title: "氣體交換膜模型", text: "研究者製作三個相同投影面積的氣體交換模型。甲使用厚乾膜且膜後液體不流動；乙使用薄濕膜但膜後液體不流動；丙使用薄濕膜且膜後液體持續更新。十分鐘後測量通過膜的氧量。", note: "模型用來比較膜厚、濕潤與流動更新，不等同完整肺臟。" },
  { summary: "表格比較三種膜厚、表面狀態、液體流動與氧通過量。", colorIndependent: true, dataFallback: { columns: ["模型", "膜", "膜後液體", "氧通過量"], rows: [["甲", "厚且乾", "不流動", "2"], ["乙", "薄且濕", "不流動", "8"], ["丙", "薄且濕", "持續更新", "15"]] } },
  [
    question("BIO_R4_SQ_058_01", "BIO_R4_S058", "standard", "哪個模型最接近肺泡薄濕壁與持續血流的條件？", ["三者完全相同", "甲模型", "乙模型", "丙模型"], 3, ["三模型的條件與結果都不同。", "甲膜厚乾且液體不流動。", "乙缺少膜後液體持續更新。", "丙同時具有薄濕膜與流動更新。"], ["肺泡交換需薄濕界面，周圍微血管又要持續更新血液。", "丙完整符合兩組條件，也有最高氧通過量。"]),
    question("BIO_R4_SQ_058_02", "BIO_R4_S058", "advanced", "比較乙與丙，何者最能解釋丙的氧通過量較高？", ["流動液體持續帶走氧並維持濃度差", "丙的膜比較厚", "乙完全沒有膜", "丙把氧製造成水"], 0, ["兩者主要差異為膜後液體是否更新。", "乙丙都使用薄濕膜。", "乙仍有薄濕膜可進行交換。", "氧通過膜不等於製造成水。"], ["乙丙控制膜條件相同，流動更新是可解釋差異的變因。", "「流動液體持續帶走氧並維持濃度差」對應微血管血流維持濃度差的生理角色。"]),
    question("BIO_R4_SQ_058_03", "BIO_R4_S058", "transfer", "若要單獨檢驗膜厚的影響，應如何改進設計？", ["同時改膜厚與液體流速", "保持濕潤與流動相同，只改膜厚", "只比較不同顏色外殼", "刪除所有氧量測量"], 1, ["兩個變因同時改會混淆原因。", "單一改變厚度可公平比較交換距離。", "外殼顏色不是交換條件。", "沒有氧量就無法比較交換結果。"], ["研究膜厚必須控制濕潤、面積與流動，只讓厚度不同。", "「保持濕潤與流動相同，只改膜厚」符合單一變因，能把氧通過量差異歸因於交換距離。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S059", "BIO_R4_S059",
  ["由肺泡與血液的氣體濃度差判斷氧、二氧化碳淨移動方向。", "說明換氣與血流如何更新兩側濃度並維持淨交換。"],
  [
    { id: "BIO_R4_L_S059_SEC_01", title: "由高濃度向低濃度淨移動", content: "在薄膜可通透且沒有其他限制時，氣體分子會雙向隨機移動，但整體淨效果是由濃度較高的一側移向較低的一側。判題需比較同一種氣體兩側濃度。" },
    { id: "BIO_R4_L_S059_SEC_02", title: "氧由肺泡進入血液", content: "吸入氣更新肺泡後，肺泡氧濃度通常高於剛到肺部的血液，因此氧的淨移動方向是由肺泡跨過薄壁進入微血管。進入血液後可與血紅素結合並被運走。" },
    { id: "BIO_R4_L_S059_SEC_03", title: "二氧化碳由血液進入肺泡", content: "來自組織的血液二氧化碳濃度通常高於肺泡氣，二氧化碳便淨移入肺泡，再隨呼氣排出。氧與二氧化碳方向不同，因為各自比較的濃度差不同。" },
    { id: "BIO_R4_L_S059_SEC_04", title: "平衡與持續更新", content: "若兩側同一氣體濃度相同，淨移動接近零，但分子仍可能雙向移動。換氣更新肺泡氣、血流更新微血管血液，可避免很快達到平衡，使交換持續。" },
  ],
  [
    { id: "BIO_R4_L_S059_EX_01", prompt: "肺泡氧濃度14，血液氧濃度5，氧淨移向哪裡？", steps: ["只比較氧在兩側的濃度。", "由較高的肺泡側指向較低的血液側。"], answer: "由肺泡進入血液", why: "肺泡氧濃度14高於血液5，薄膜兩側形成濃度差，因此氧的淨移動由肺泡指向血液。" },
    { id: "BIO_R4_L_S059_EX_02", prompt: "血液二氧化碳濃度9，肺泡為4，方向如何？", steps: ["比較二氧化碳而不是氧。", "由血液高濃度側指向肺泡低濃度側。"], answer: "由血液進入肺泡", why: "二氧化碳在血液側較高，會淨移入肺泡，之後隨呼氣排出；不能套用氧的方向。" },
    { id: "BIO_R4_L_S059_EX_03", prompt: "兩側氧濃度相同，能否說氧分子完全不動？", steps: ["區分分子隨機運動與整體淨移動。", "比較雙向通過量是否相抵。"], answer: "不能，只能說淨移動接近零", why: "濃度相同時，兩方向平均通過量相近而互相抵銷，分子仍保持隨機運動，並非全部靜止。" },
  ],
  [
    { belief: "氧和二氧化碳一定朝同一方向移動。", whyWrong: "兩種氣體各自有濃度差，肺泡與血液的高低側不同。", correction: "每次只比較同一種氣體兩側濃度，再判斷其淨方向。" },
    { belief: "氣體會由低濃度側自動跑向高濃度側。", whyWrong: "一般擴散的淨效果是由高濃度側移向低濃度側。", correction: "先標出高低濃度，再畫由高指向低的淨移動箭頭。" },
    { belief: "濃度相同表示所有分子都停止運動。", whyWrong: "分子仍雙向隨機運動，只是兩方向通過量平均相抵。", correction: "把平衡描述為淨移動接近零，不描述為分子靜止。" },
    { belief: "肺泡一換氣就不需要微血管血流。", whyWrong: "血流也需帶走氧、帶來二氧化碳，才能維持血液側濃度差。", correction: "換氣更新肺泡側，血流更新血液側，兩者共同維持交換。" },
  ],
  [
    { prompt: "肺泡氧較高時，氧淨移向哪裡？", answer: "血液", reason: "氧由肺泡高濃度側跨薄壁移向血液低濃度側。" },
    { prompt: "血液二氧化碳較高時，淨移向哪裡？", answer: "肺泡", reason: "二氧化碳由血液高濃度側移入肺泡，再隨呼氣排出。" },
    { prompt: "兩側濃度相同時，淨移動如何？", answer: "接近零", reason: "兩方向分子通過量平均相抵，但分子本身仍持續隨機運動。" },
  ],
));

questions.push(
  question("BIO_R4_Q_059_01", "BIO_R4_S059", "foundation", "同一氣體存在濃度差時，淨移動通常朝哪個方向？", ["高濃度側到低濃度側", "低濃度側到高濃度側", "只向上移動", "完全停止移動"], 0, ["一般擴散淨效果由高濃度移向低濃度。", "此方向與濃度擴散趨勢相反。", "氣體淨方向不由上下位置單獨決定。", "有濃度差時通常存在淨移動。"], ["判斷擴散先比較同一氣體兩側濃度，再由高指向低。", "「高濃度側到低濃度側」符合濃度差，其他選項顛倒、加入無關方向或否定移動。"]),
  question("BIO_R4_Q_059_02", "BIO_R4_S059", "foundation", "肺泡氧濃度高於微血管血液時，氧淨移向哪裡？", ["由血液進肺泡", "由肺泡進血液", "由肺泡進胃", "由血液進小腸"], 1, ["此方向是由低氧血到高氧肺泡。", "由高濃度肺泡到低濃度血液正確。", "胃不與肺泡進行氧交換。", "小腸也不是肺泡氣體的直接去向。"], ["只比較氧，肺泡側較高，所以淨方向為肺泡到微血管。", "「由肺泡進血液」符合濃度梯度與交換界面，其餘方向或器官錯誤。"]),
  question("BIO_R4_Q_059_03", "BIO_R4_S059", "foundation", "血液二氧化碳濃度高於肺泡氣時，淨移向哪裡？", ["組織細胞", "小腸腔", "肺泡", "膀胱"], 2, ["題幹比較的是肺部血液與肺泡。", "小腸不參與肺部二氧化碳交換。", "二氧化碳由血液高濃度側進肺泡。", "膀胱只儲存尿液。"], ["血液側二氧化碳較高，依擴散方向應淨移入肺泡。", "「肺泡」位於交換膜另一側，其餘構造不在此氣體梯度中。"]),
  question("BIO_R4_Q_059_04", "BIO_R4_S059", "standard", "兩側氧濃度相同時，最適當的敘述為何？", ["氧分子全部停止", "氧只能進入血液", "氧只能進入肺泡", "雙向移動仍有，但淨移動接近零"], 3, ["分子熱運動不會因平衡完全停止。", "沒有高低差不能只指定單向。", "同樣也不能只指定反方向。", "雙向量相抵可使淨值接近零。"], ["平衡描述的是整體淨效果，不代表每個分子靜止。", "「雙向移動仍有，但淨移動接近零」正確區分微觀雙向運動與宏觀淨移動。"]),
  question("BIO_R4_Q_059_05", "BIO_R4_S059", "standard", "肺泡氧為13單位、血液氧為6單位，氧的淨方向為何？", ["肺泡到血液", "血液到肺泡", "肺泡到食道", "兩側完全相同"], 0, ["13高於6，氧由肺泡淨移向血液。", "此方向由低濃度指向高濃度。", "食道不在肺泡交換界面。", "兩個氧濃度數值明顯不同。"], ["比較數值13與6，肺泡是高濃度側，血液是低濃度側。", "「肺泡到血液」可由數據直接導出，沒有第二個合理方向。"]),
  question("BIO_R4_Q_059_06", "BIO_R4_S059", "standard", "肺泡二氧化碳為4、血液為10，淨方向為何？", ["肺泡到血液", "血液到肺泡", "肺泡到胃", "完全沒有移動"], 1, ["此方向由4指向10，與擴散相反。", "二氧化碳由10的血液側進入4的肺泡側。", "胃不與肺泡交換二氧化碳。", "存在濃度差時有淨移動。"], ["這次比較二氧化碳，血液10高於肺泡4。", "「血液到肺泡」由高濃度到低濃度，不能誤套用氧的方向。"]),
  question("BIO_R4_Q_059_07", "BIO_R4_S059", "standard", "持續換氣對肺泡氣體交換有何幫助？", ["使肺泡壁變成胃壁", "讓血液完全停止", "更新肺泡氣並維持濃度差", "把氧全部變成二氧化碳"], 2, ["換氣不會改變器官組織種類。", "換氣與血流都需持續而非停止。", "新鮮空氣可補氧並排出二氧化碳。", "換氣只是移動氣體，不進行此物質轉變。"], ["肺泡氣若不更新會逐漸接近平衡，淨交換下降。", "「更新肺泡氣並維持濃度差」正確說明換氣維持肺泡側濃度條件的作用。"]),
  question("BIO_R4_Q_059_08", "BIO_R4_S059", "advanced", "血流加快後肺部氧交換可能增加，最合理原因為何？", ["血液把肺泡變大", "血流製造新的肺泡", "血液使氧分子靜止", "較快帶走氧並帶來低氧血，維持濃度差"], 3, ["血流不會直接改變肺泡尺寸。", "肺泡數量也不是由即時血流製造。", "氧分子仍保持隨機運動。", "更新血液可維持交換梯度。"], ["血流的關鍵不是製造氧，而是更新交換膜血液側的濃度。", "「較快帶走氧並帶來低氧血，維持濃度差」同時說明運走與帶來，能維持氧由肺泡進血的淨方向。"]),
  question("BIO_R4_Q_059_09", "BIO_R4_S059", "advanced", "氧由肺泡進血、二氧化碳由血進肺泡，為何方向相反？", ["兩種氣體各自的濃度高低位置不同", "氧只會向左，二氧化碳只會向右", "肺泡壁只讓氧單向通過", "血液完全不含氧"], 0, ["各自比較濃度即可得到相反淨方向。", "方向不由固定左右位置決定。", "肺泡壁可讓兩種氣體雙向通過。", "到肺的血液仍含氧，只是相對較低。"], ["擴散規則相同，但氧與二氧化碳在兩側的濃度排列相反。", "「兩種氣體各自的濃度高低位置不同」能以同一規則解釋兩個方向，不需假設膜單向。"]),
  question("BIO_R4_Q_059_10", "BIO_R4_S059", "advanced", "若肺泡停止換氣但血流持續，氧淨交換會逐漸如何？", ["無限增加", "因肺泡氧下降而逐漸減少", "立刻使血液沒有水", "轉變成養分吸收"], 1, ["缺少新鮮空氣不會讓氧梯度無限增加。", "氧被血液帶走後肺泡側濃度會下降。", "血液含水不由肺泡換氣立即決定。", "肺部交換不會變成小腸吸收。"], ["沒有換氣補充氧，肺泡與血液氧差會逐漸縮小。", "「因肺泡氧下降而逐漸減少」符合濃度差變化，其他選項跨越物質或器官功能。"]),
  question("BIO_R4_Q_059_11", "BIO_R4_S059", "transfer", "人工膜一側氧20、另一側氧8，若膜可通透，預測何者正確？", ["氧淨由8移向20", "氧完全不動", "氧淨由20移向8", "氧先變成二氧化碳"], 2, ["此方向由低濃度到高濃度。", "兩側濃度不同會有淨移動。", "由高濃度20到低濃度8符合擴散。", "跨膜移動不會改變氣體種類。"], ["人工膜仍可使用濃度差規則，20側是高濃度。", "「氧淨由20移向8」是由高到低的唯一方向，無需把氧轉成其他物質。"]),
  question("BIO_R4_Q_059_12", "BIO_R4_S059", "transfer", "登高時外界氧較低，肺泡到血液的氧濃度差可能如何？", ["一定變成無限大", "與外界氧完全無關", "使二氧化碳全部消失", "可能縮小，使氧淨移動減少"], 3, ["外界氧降低不會讓梯度無限增加。", "肺泡氧會受吸入空氣影響。", "氧變化不會使二氧化碳全部消失。", "肺泡氧下降可縮小對血液的濃度差。"], ["高地吸入氧較低時，肺泡側氧濃度可能下降，交換驅動力變小。", "「可能縮小，使氧淨移動減少」以可能表述合理推論，沒有作超出條件的絕對宣稱。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S059", "BIO_R4_S059", "gas-gradient-table",
  { title: "肺泡與微血管氣體資料", text: "研究者在氣體交換開始時測得肺泡氣與剛到肺部微血管血液的相對濃度。數值越大表示該氣體相對濃度越高，交換膜可讓氧與二氧化碳通過。", note: "資料只用於判斷淨移動方向，不代表分子只朝單一方向運動。" },
  { summary: "表格比較肺泡與微血管中氧、二氧化碳的相對濃度。", colorIndependent: true, dataFallback: { columns: ["氣體", "肺泡氣", "微血管血液"], rows: [["氧", "14", "5"], ["二氧化碳", "4", "10"]] } },
  [
    question("BIO_R4_SQ_059_01", "BIO_R4_S059", "standard", "依資料，氧的淨移動方向為何？", ["肺泡到胃", "血液到肺泡", "肺泡到血液", "兩側沒有差異"], 2, ["胃不位於肺泡交換膜另一側。", "此方向由低濃度5移向高濃度14。", "肺泡氧14高於血液5，淨方向進血。", "兩側氧數值明顯不同。"], ["比較氧的兩個數值，肺泡側14較高，血液側5較低。", "「肺泡到血液」符合由高到低的擴散淨方向。"]),
    question("BIO_R4_SQ_059_02", "BIO_R4_S059", "advanced", "依資料，二氧化碳的淨移動方向為何？", ["肺泡到血液", "完全不移動", "鼻腔到血液", "血液到肺泡"], 3, ["肺泡4低於血液10，方向不會由低到高。", "有明顯濃度差時存在淨移動。", "鼻腔不是此表的交換界面。", "血液10較高，二氧化碳淨移入肺泡。"], ["二氧化碳需另行比較，血液側10高於肺泡側4。", "「血液到肺泡」符合濃度差，也解釋二氧化碳如何進入呼出氣。"]),
    question("BIO_R4_SQ_059_03", "BIO_R4_S059", "transfer", "若血流停止，過一段時間最可能出現什麼？", ["鄰近血液氣體濃度接近平衡，淨交換下降", "肺泡立即變成胃", "濃度差永遠保持不變", "氧全部變成水"], 0, ["局部兩側逐漸接近會降低淨交換。", "血流停止不會改變器官種類。", "沒有血流更新，局部濃度會隨交換改變。", "擴散不會把氧轉變成水。"], ["血流原本負責帶走氧並帶來二氧化碳，停止後更新消失。", "「鄰近血液氣體濃度接近平衡，淨交換下降」是由濃度差縮小推得的直接後果。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S060", "BIO_R4_S060",
  ["區分呼吸運動、氣體交換與細胞呼吸的場所與作用。", "由胸腔、肺泡、血液與細胞證據辨識三個相連但不同的過程。"],
  [
    { id: "BIO_R4_L_S060_SEC_01", title: "呼吸運動使空氣進出", content: "呼吸運動是橫膈與肋間肌等活動改變胸腔容積，使空氣吸入或呼出。它描述機械性通氣，不等於氧已進入血液，也不直接釋放養分能量。" },
    { id: "BIO_R4_L_S060_SEC_02", title: "氣體交換跨越薄膜", content: "肺泡氣體交換是氧與二氧化碳在肺泡和微血管之間移動；組織處也有血液與細胞間的氣體交換。判斷關鍵是氣體跨越交換界面。" },
    { id: "BIO_R4_L_S060_SEC_03", title: "細胞呼吸發生在細胞內", content: "細胞呼吸是一連串化學反應，細胞利用氧與養分釋放可用能量，並產生二氧化碳等物質。它不等同肺吸氣，也不是肺泡把養分直接燃燒。" },
    { id: "BIO_R4_L_S060_SEC_04", title: "三過程彼此接續", content: "呼吸運動更新肺泡氣，肺泡交換使氧進血，循環把氧送到細胞，細胞呼吸再利用氧與養分。三者互相支持，但場所、物質變化與直接結果不同。" },
  ],
  [
    { id: "BIO_R4_L_S060_EX_01", prompt: "橫膈收縮使空氣進肺，屬於哪個過程？", steps: ["辨認肌肉與胸腔容積改變。", "確認描述的是空氣整體進出。"], answer: "呼吸運動", why: "題幹只有機械性通氣證據，尚未描述氧跨肺泡壁或細胞內養分反應，因此應判為呼吸運動。" },
    { id: "BIO_R4_L_S060_EX_02", prompt: "氧由肺泡進入微血管，屬於哪個過程？", steps: ["找出氧跨越肺泡與血液界面。", "區分空氣進肺與氣體跨膜。"], answer: "氣體交換", why: "氧已由肺泡腔穿過薄壁到血液，這是肺部氣體交換，不只是胸腔擴張造成的吸氣。" },
    { id: "BIO_R4_L_S060_EX_03", prompt: "肌肉細胞利用葡萄糖與氧釋放能量，屬於什麼？", steps: ["定位反應場所為肌肉細胞。", "辨認養分、氧與能量轉換。"], answer: "細胞呼吸", why: "細胞內養分參與化學反應並釋放可用能量，是細胞呼吸的定義，不是肺泡交換或空氣流動。" },
  ],
  [
    { belief: "胸腔一擴張就表示細胞已釋放能量。", whyWrong: "胸腔擴張只直接造成吸氣，氧還需交換、運輸與細胞利用。", correction: "把空氣進出、氧入血與細胞能量反應依序分開。" },
    { belief: "氧進入肺泡就等於已進入血液。", whyWrong: "肺泡腔與微血管之間仍隔著肺泡壁和血管壁。", correction: "到達肺泡屬通氣，跨過薄壁進血才是氣體交換。" },
    { belief: "細胞呼吸只發生在肺部。", whyWrong: "全身需要能量的活細胞都可進行細胞呼吸，肺主要負責換氣。", correction: "肺部提供氣體交換，細胞呼吸則發生在各組織細胞內。" },
    { belief: "氣體交換會直接把葡萄糖分解。", whyWrong: "交換只使氧與二氧化碳跨膜，葡萄糖分解屬細胞內化學反應。", correction: "以是否跨膜或是否有養分反應區分氣體交換與細胞呼吸。" },
  ],
  [
    { prompt: "橫膈活動造成吸氣屬於什麼？", answer: "呼吸運動", reason: "肌肉改變胸腔容積並驅動空氣進出，是機械性通氣過程。" },
    { prompt: "氧跨肺泡壁進血屬於什麼？", answer: "氣體交換", reason: "氧由肺泡腔跨越薄壁進入微血管，符合跨膜交換判準。" },
    { prompt: "細胞利用養分釋放能量屬於什麼？", answer: "細胞呼吸", reason: "養分在細胞內參與反應並釋放能量，是細胞呼吸作用。" },
  ],
));

questions.push(
  question("BIO_R4_Q_060_01", "BIO_R4_S060", "foundation", "橫膈與肋間肌活動使空氣進出肺，稱為什麼？", ["呼吸運動", "氣體交換", "細胞呼吸", "養分吸收"], 0, ["肌肉改變胸腔容積，屬機械性呼吸運動。", "題幹沒有氣體跨越肺泡壁。", "也沒有細胞內養分能量反應。", "養分吸收主要發生在小腸。"], ["判斷線索是呼吸肌活動與空氣進出，直接對應呼吸運動。", "其他過程分別需要跨膜、細胞化學反應或腸壁運輸證據。"]),
  question("BIO_R4_Q_060_02", "BIO_R4_S060", "foundation", "氧由肺泡穿過薄壁進入微血管，稱為什麼？", ["呼吸運動", "氣體交換", "細胞呼吸", "排遺"], 1, ["呼吸運動只直接更新肺泡空氣。", "氧跨肺泡與血液界面是氣體交換。", "細胞呼吸發生在細胞內。", "排遺是排出食物殘餘。"], ["題幹有氧跨越肺泡壁並進入血液的明確方向。", "「氣體交換」符合交換界面，其餘過程的場所與物質皆不同。"]),
  question("BIO_R4_Q_060_03", "BIO_R4_S060", "foundation", "肌肉細胞利用養分與氧釋放能量，屬於哪個過程？", ["吞嚥", "肺泡換氣", "細胞呼吸", "小腸吸收"], 2, ["吞嚥只把食團送入消化道。", "肺泡換氣是空氣更新而非細胞反應。", "養分與氧在細胞內反應正是細胞呼吸。", "小腸吸收讓養分進入循環。"], ["場所是肌肉細胞，結果是養分能量釋放，兩項都指向細胞呼吸。", "「細胞呼吸」唯一同時符合場所與化學反應內容。"]),
  question("BIO_R4_Q_060_04", "BIO_R4_S060", "standard", "下列哪組過程與主要場所配對正確？", ["呼吸運動－小腸絨毛", "氣體交換－胃腔", "細胞呼吸－氣管管腔", "氣體交換－肺泡與微血管界面"], 3, ["呼吸運動與胸腔及呼吸肌相關。", "胃腔主要處理食物。", "細胞呼吸不在氣管管腔進行。", "肺泡薄壁是主要氣體交換界面。"], ["氣體交換需要氧與二氧化碳跨越肺泡和血液之間的薄膜。", "「氣體交換－肺泡與微血管界面」的過程與場所一致，其餘配對皆跨錯器官。"]),
  question("BIO_R4_Q_060_05", "BIO_R4_S060", "standard", "吸入空氣到達肺泡但尚未跨壁，此時直接完成什麼？", ["呼吸運動造成的通氣", "氧已送到所有細胞", "細胞已分解葡萄糖", "二氧化碳已全部排完"], 0, ["空氣到肺泡表示通氣已更新肺泡氣。", "尚未跨壁就不能說氧已進循環。", "細胞分解葡萄糖需細胞內反應。", "一次吸氣也不會排完全部二氧化碳。"], ["題幹明示尚未跨壁，所以只能確認空氣已因呼吸運動到達肺泡。", "「呼吸運動造成的通氣」保留證據界線，其他敘述跳過交換與循環步驟。"]),
  question("BIO_R4_Q_060_06", "BIO_R4_S060", "standard", "血液中的氧移入組織細胞，最直接屬於什麼？", ["呼吸運動", "組織氣體交換", "食物排遺", "尿液形成"], 1, ["呼吸運動只驅動肺內空氣進出。", "氧跨血管與細胞界面屬組織交換。", "排遺處理未消化食物殘餘。", "尿液由腎臟過濾與調節形成。"], ["氧由血液跨界面進入組織，與肺泡交換同屬氣體跨膜。", "「組織氣體交換」符合物質方向與場所，其他過程完全不同。"]),
  question("BIO_R4_Q_060_07", "BIO_R4_S060", "standard", "細胞呼吸與氣體交換最主要差別為何？", ["兩者都只讓空氣進鼻腔", "兩者都不需氧氣", "前者有細胞內能量反應，後者是氣體跨膜", "前者只在肺，後者只在胃"], 2, ["鼻腔進氣只屬呼吸運動前段。", "多數細胞呼吸與氧供應密切相關。", "此項正確區分化學反應與物理移動。", "細胞呼吸遍及組織，胃也非主要換氣處。"], ["細胞呼吸改變養分並釋放能量，氣體交換只改變氣體所在位置。", "「前者有細胞內能量反應，後者是氣體跨膜」以作用性質區分，比單用器官名稱更準確。"]),
  question("BIO_R4_Q_060_08", "BIO_R4_S060", "advanced", "某人胸腔能正常擴張，但肺泡壁嚴重增厚，哪項最可能？", ["呼吸運動停止且交換正常", "細胞呼吸立即變成吸收", "胃消化速度無限增加", "通氣可存在但氣體交換效率下降"], 3, ["胸腔能擴張表示呼吸運動未停止。", "肺泡病變不會改變作用種類。", "胃消化與肺泡壁厚無直接關係。", "薄壁受損會妨礙跨膜交換。"], ["題幹刻意保留機械通氣、破壞交換界面，兩過程可分開受影響。", "「通氣可存在但氣體交換效率下降」同時符合兩項條件，顯示通氣不等於交換。"]),
  question("BIO_R4_Q_060_09", "BIO_R4_S060", "advanced", "若血液有氧但細胞無法利用養分反應，直接受阻的是什麼？", ["細胞呼吸", "鼻腔過濾", "呼吸運動", "肺泡氣體交換"], 0, ["細胞利用氧與養分的反應受阻。", "鼻腔過濾不取決於細胞代謝能力。", "胸腔通氣也可能仍正常。", "氧已進血表示交換未必是直接問題。"], ["題幹將氧供應與細胞利用分開，故直接障礙在細胞內反應。", "「細胞呼吸」符合受阻階段，其他過程可能正常存在。"]),
  question("BIO_R4_Q_060_10", "BIO_R4_S060", "advanced", "運動時呼吸加快如何間接支持細胞呼吸？", ["把氣管變成細胞", "更新肺泡氣，促進氧交換與運送", "直接在肺泡製造葡萄糖", "讓所有二氧化碳變成氧"], 1, ["器官管道不會轉變成單一細胞。", "通氣增加可協助維持肺泡氣體梯度。", "肺泡不負責製造葡萄糖。", "呼吸運動也不會轉換氣體元素。"], ["呼吸運動本身不釋能，但可更新肺泡氣並支持氧進血。", "「更新肺泡氣，促進氧交換與運送」描述間接鏈結，沒有把通氣誤寫成細胞化學反應。"]),
  question("BIO_R4_Q_060_11", "BIO_R4_S060", "transfer", "潛水呼吸管堵塞時，最先直接受影響的過程是什麼？", ["肌肉細胞立即失去所有養分", "小腸絨毛消失", "空氣進出的呼吸運動效果", "腎臟停止製尿"], 2, ["細胞養分不會因短暫堵塞立即全部消失。", "呼吸管不直接改變小腸構造。", "通道堵塞先妨礙空氣進出肺。", "腎臟製尿也不是最先直接影響。"], ["阻塞位於空氣入口，因此最先破壞呼吸運動所造成的通氣效果。", "「空氣進出的呼吸運動效果」依路徑定位，後續交換與細胞呼吸才可能間接受影響。"]),
  question("BIO_R4_Q_060_12", "BIO_R4_S060", "transfer", "實驗只量到胸腔容積變化，最能直接研究哪個過程？", ["細胞內能量產量", "葡萄糖進小腸微血管", "氧跨肺泡壁速率", "呼吸運動"], 3, ["胸腔容積不能直接量細胞能量。", "小腸吸收也不由胸腔容積表示。", "跨膜速率還需氣體或血液資料。", "胸腔容積變化直接反映機械通氣。"], ["測量指標決定結論範圍，胸腔容積是呼吸運動的直接表現。", "「呼吸運動」最符合資料，其餘過程需要不同場所與物質測量。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S060", "BIO_R4_S060", "process-observations",
  { title: "三項呼吸觀察", text: "研究者分別記錄三項現象：甲為吸氣時胸腔容積增加；乙為氧由肺泡進入微血管；丙為肌肉細胞消耗氧並產生較多二氧化碳，同時可用能量增加。", note: "三項現象可前後連結，但分類時依直接場所與作用判斷。" },
  { summary: "表格列出胸腔、肺泡與肌肉細胞三種觀察。", colorIndependent: true, dataFallback: { columns: ["觀察", "場所", "直接變化"], rows: [["甲", "胸腔", "容積增加、空氣進肺"], ["乙", "肺泡與微血管", "氧跨薄壁進血"], ["丙", "肌肉細胞", "耗氧、產二氧化碳、可用能量增加"]] } },
  [
    question("BIO_R4_SQ_060_01", "BIO_R4_S060", "standard", "甲觀察最直接代表哪個過程？", ["氣體交換", "呼吸運動", "細胞呼吸", "養分吸收"], 1, ["甲未描述氣體跨肺泡壁。", "胸腔容積增加驅動空氣進肺。", "甲也沒有細胞內養分反應。", "養分吸收發生在小腸。"], ["場所為胸腔、結果為空氣進肺，直接對應呼吸運動。", "不能因最終供氧就把甲提前分類為氣體交換或細胞呼吸。"]),
    question("BIO_R4_SQ_060_02", "BIO_R4_S060", "advanced", "乙觀察與甲最主要的差異是什麼？", ["乙在小腸分解食物", "甲會產生尿液", "乙描述氣體跨膜而甲描述空氣進出", "兩者作用完全相同"], 2, ["乙的場所是肺泡與微血管。", "胸腔容積變化不直接形成尿液。", "兩者分別是交換與機械通氣。", "場所與直接變化都明顯不同。"], ["甲更新肺泡氣，乙才讓氧跨越肺泡壁進入血液。", "「乙描述氣體跨膜而甲描述空氣進出」精確區分通氣與交換，同時保留兩者前後關係。"]),
    question("BIO_R4_SQ_060_03", "BIO_R4_S060", "transfer", "若甲乙正常但丙的可用能量不增加，優先檢查什麼？", ["鼻腔是否有鼻毛", "大腸是否吸水", "牙齒是否磨碎食物", "細胞內養分反應是否受阻"], 3, ["鼻毛不直接控制細胞能量反應。", "大腸吸水也不是丙的場所。", "咀嚼與題幹氧供應無直接對應。", "通氣交換正常後應檢查細胞利用階段。"], ["甲乙正常表示空氣進肺與氧入血可進行，問題落在細胞利用。", "「細胞內養分反應是否受阻」沿過程順序定位，符合丙的場所與能量指標。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S061", "BIO_R4_S061",
  ["說明細胞呼吸由養分反應釋放並轉換可用能量。", "連結氧、養分、二氧化碳與活動需求，避免把氧或酵素視為能量。"],
  [
    { id: "BIO_R4_L_S061_SEC_01", title: "養分含有可轉換的化學能", content: "食物消化吸收後，葡萄糖等養分被運到細胞，其中的化學能可在細胞呼吸反應中轉換。能量不是由細胞憑空創造，也不是食物一進胃就全部可用。" },
    { id: "BIO_R4_L_S061_SEC_02", title: "氧參與能量釋放反應", content: "多數人體細胞呼吸需要氧參與，並產生二氧化碳與水等物質。氧有助養分充分反應，但氧本身不是熱量，也不能在沒有養分時獨自提供活動能量。" },
    { id: "BIO_R4_L_S061_SEC_03", title: "可用能量支持生命活動", content: "細胞呼吸釋出的可用能量支持肌肉收縮、物質合成、主動運輸與維持體溫等生命活動。不同活動耗能不同，因此活動增加時，氧與養分供應及代謝速率常跟著調整。" },
    { id: "BIO_R4_L_S061_SEC_04", title: "物質與能量分開追蹤", content: "葡萄糖與氧是反應物，二氧化碳與水是產物，能量則是反應中轉換釋出的結果。物質會重新組合，能量以可用形式與熱等形式轉換，不能把二氧化碳直接稱為能量。" },
  ],
  [
    { id: "BIO_R4_L_S061_EX_01", prompt: "肌肉細胞同時消耗葡萄糖與氧，最可能增加什麼？", steps: ["辨認兩者都是細胞呼吸反應物。", "連結反應進行與可用能量釋出。"], answer: "細胞可利用的能量", why: "葡萄糖與氧參與細胞呼吸，可將養分中的化學能轉成細胞可用形式，以支持肌肉收縮等活動。" },
    { id: "BIO_R4_L_S061_EX_02", prompt: "只有氧而沒有養分，能否持續提供細胞活動能量？", steps: ["區分氧與含化學能的養分。", "檢查反應是否具備主要物質來源。"], answer: "不能", why: "氧是細胞呼吸的重要反應物之一，但可轉換的化學能主要來自養分；缺少養分時不能只靠氧持續供能。" },
    { id: "BIO_R4_L_S061_EX_03", prompt: "細胞呼吸產生二氧化碳，能否說二氧化碳就是能量？", steps: ["把物質產物與能量結果分欄。", "確認二氧化碳可被運到肺排出。"], answer: "不能", why: "二氧化碳是含碳物質反應後的物質產物，能量則以可用形式與熱等方式轉換，兩者不是同一類概念。" },
  ],
  [
    { belief: "細胞呼吸會憑空製造能量。", whyWrong: "能量來自養分所含化學能的轉換，並非由無到有。", correction: "描述為釋放與轉換養分能量，不使用創造能量的說法。" },
    { belief: "氧就是細胞活動使用的能量。", whyWrong: "氧是反應物，能量主要來自養分中的化學能轉換。", correction: "氧協助養分反應，養分提供可轉換能量，兩者角色分開。" },
    { belief: "細胞呼吸只在運動時才發生。", whyWrong: "休息時細胞仍需能量維持基本生命活動，只是需求可能較低。", correction: "把細胞呼吸視為持續作用，活動強度只會改變需求速率。" },
    { belief: "二氧化碳越多表示它提供越多能量。", whyWrong: "二氧化碳是反應產物與廢物，不是細胞可用能量本身。", correction: "二氧化碳產量可作代謝指標，但不能把產物等同能量。" },
  ],
  [
    { prompt: "細胞呼吸的能量主要來自哪裡？", answer: "養分中的化學能", reason: "養分參與反應時，其化學能轉成細胞可利用形式與熱。" },
    { prompt: "氧在細胞呼吸中是能量本身嗎？", answer: "不是", reason: "氧是反應物之一，不能在沒有養分時獨自提供化學能。" },
    { prompt: "細胞呼吸產生的氣體產物為何？", answer: "二氧化碳", reason: "含碳養分反應後可產生二氧化碳，再由循環送往肺排出。" },
  ],
));

questions.push(
  question("BIO_R4_Q_061_01", "BIO_R4_S061", "foundation", "人體細胞呼吸可用能量主要來自哪裡？", ["養分中的化學能", "鼻腔中的空氣重量", "肺泡的數量", "尿液中的水"], 0, ["養分反應可把化學能轉成細胞可用形式。", "空氣重量不是細胞活動的能量來源。", "肺泡數量影響交換面積而非直接供能。", "尿液中的水也不是細胞呼吸燃料。"], ["細胞呼吸處理養分與氧，能量來源需追溯到養分化學能。", "「養分中的化學能」符合能量轉換，其他選項只是物質或構造特徵。"]),
  question("BIO_R4_Q_061_02", "BIO_R4_S061", "foundation", "多數人體細胞呼吸除了養分，還需要哪種氣體參與？", ["氮氣", "氧氣", "水蒸氣", "氦氣"], 1, ["氮氣不是人體細胞呼吸主要反應氣體。", "氧氣參與養分能量釋放相關反應。", "水蒸氣不是此處主要反應物判準。", "氦氣也不參與正常細胞呼吸。"], ["人體多數細胞進行有氧呼吸時，需要氧與養分共同參與。", "「氧氣」是唯一符合生理反應的氣體，其他成分沒有此角色。"]),
  question("BIO_R4_Q_061_03", "BIO_R4_S061", "foundation", "細胞呼吸常產生並需由肺排出的氣體是什麼？", ["氧氣", "氮氣", "二氧化碳", "氦氣"], 2, ["氧氣多為細胞呼吸反應物。", "氮氣不是主要代謝氣體產物。", "二氧化碳可由細胞產生並送肺排出。", "人體也不會代謝產生氦氣。"], ["含碳養分參與細胞呼吸後可形成二氧化碳。", "「二氧化碳」符合細胞到血液再到肺的排出路徑，其他氣體不符合。"]),
  question("BIO_R4_Q_061_04", "BIO_R4_S061", "standard", "下列哪項最完整描述細胞呼吸？", ["肺泡把空氣吸進鼻腔", "小腸把食物變成糞便", "血液只運送氧而不運養分", "細胞利用養分與氧進行反應並釋放可用能量"], 3, ["空氣方向與作用場所都不正確。", "小腸主要消化吸收而非此定義。", "血液可同時運送氧與多種養分。", "此項包含場所、反應物與能量結果。"], ["完整定義需有細胞場所、養分與氧、能量轉換三個要素。", "「細胞利用養分與氧進行反應並釋放可用能量」符合全部要素，其他選項描述呼吸、消化或錯誤運輸。"]),
  question("BIO_R4_Q_061_05", "BIO_R4_S061", "standard", "氧在細胞呼吸中的角色，哪項敘述最正確？", ["是反應物之一，但不是能量本身", "沒有養分也能單獨無限供能", "會直接變成葡萄糖", "只負責形成糞便"], 0, ["氧參與反應，能量則來自養分化學能轉換。", "缺少養分時氧不能單獨持續供能。", "氧不會在細胞呼吸中變成葡萄糖。", "糞便形成屬消化道排遺。"], ["要避免把物質與能量混淆，氧是反應物而非可用能量。", "「是反應物之一，但不是能量本身」精確限定氧的角色，「沒有養分也能單獨無限供能」、「會直接變成葡萄糖」、「只負責形成糞便」皆誇大或錯配。"]),
  question("BIO_R4_Q_061_06", "BIO_R4_S061", "standard", "休息時細胞仍進行呼吸，主要原因為何？", ["休息代表所有細胞停止", "維持基本生命活動仍需要能量", "只有胃需要氧氣", "二氧化碳會變成全部養分"], 1, ["休息時細胞仍有持續的生命作用。", "物質運輸、合成與維持狀態都需能量。", "全身多數活細胞都需要氧供。", "二氧化碳不會轉成全部養分。"], ["身體休息不等於細胞停止工作，基本代謝仍持續。", "「維持基本生命活動仍需要能量」說明能量需求，因此細胞呼吸在休息時也不會完全停止。"]),
  question("BIO_R4_Q_061_07", "BIO_R4_S061", "standard", "細胞呼吸產生的二氧化碳接下來通常如何處理？", ["直接變成蛋白質", "留在細胞無限累積", "進入血液並運往肺排出", "由小腸吸收回食物"], 2, ["二氧化碳不會直接成為蛋白質。", "持續累積會干擾內環境，需被運走。", "循環可把二氧化碳帶到肺泡交換。", "小腸不會把代謝氣體吸回食物。"], ["細胞產生的二氧化碳先進入組織血液，再由循環送往肺。", "「進入血液並運往肺排出」連結細胞呼吸、循環與呼吸系統，是正常處理路徑。"]),
  question("BIO_R4_Q_061_08", "BIO_R4_S061", "advanced", "肌肉活動增加時，耗氧與二氧化碳產生都增加，最合理解釋為何？", ["肌肉停止使用能量", "氧直接變成肌肉組織", "二氧化碳提供全部能量", "細胞呼吸速率提高以供應活動能量"], 3, ["活動增加反而需要更多可用能量。", "氧參與反應但不直接變成肌肉。", "二氧化碳是產物而不是能量來源。", "兩項氣體變化符合呼吸反應加快。"], ["耗氧與產二氧化碳同時提高，是細胞呼吸速率增加的物質證據。", "「細胞呼吸速率提高以供應活動能量」也能解釋肌肉活動的能量需求，其他選項角色錯置。"]),
  question("BIO_R4_Q_061_09", "BIO_R4_S061", "advanced", "若細胞有充足氧卻缺乏養分，最可能限制什麼？", ["可供轉換的化學能來源", "肺泡總面積一定消失", "氧在空氣中的濃度", "鼻腔過濾顆粒"], 0, ["缺養分會缺少細胞呼吸的能量物質來源。", "細胞養分不足不會使肺泡構造消失。", "外界氧濃度也未必因此改變。", "鼻腔過濾與細胞養分沒有直接因果。"], ["氧不是能量本身，沒有養分便缺少可被反應轉換的化學能。", "「可供轉換的化學能來源」符合反應物角色，其他選項是無關呼吸構造或環境。"]),
  question("BIO_R4_Q_061_10", "BIO_R4_S061", "advanced", "如何證明二氧化碳是細胞呼吸產物而非能量本身？", ["只看細胞顏色", "測得反應時二氧化碳增加並被運走排出", "把二氧化碳名稱改掉", "停止記錄養分與氧"], 1, ["顏色不能直接區分物質與能量角色。", "產生、運走與排出符合物質產物特徵。", "改名稱不會改變其化學性質。", "刪除關鍵資料反而無法判斷反應。"], ["物質產物可被定量並沿血液到肺排出，能量則不是這種運輸物。", "「測得反應時二氧化碳增加並被運走排出」提供可檢驗證據，明確支持二氧化碳的物質角色。"]),
  question("BIO_R4_Q_061_11", "BIO_R4_S061", "transfer", "發酵槽內細胞耗用糖並放出熱，最合理的能量解釋為何？", ["熱由無到有被創造", "糖完全沒有能量", "糖的化學能在反應中轉換並部分成熱", "氧就是所有熱量"], 2, ["能量轉換不應描述為憑空創造。", "糖含有可在反應中轉換的化學能。", "此項符合物質反應與熱釋放觀察。", "即使有氧也不能把氧等同全部熱量。"], ["耗糖與放熱共同支持養分化學能轉換，而非能量創造。", "「糖的化學能在反應中轉換並部分成熱」能解釋兩項觀察，也符合能量以不同形式轉換。"]),
  question("BIO_R4_Q_061_12", "BIO_R4_S061", "transfer", "運動員只增加吸氧卻完全不補充養分，為何不能長期維持高強度？", ["氧會把肺泡變成胃", "養分只用來形成尿液", "吸氧會停止血液循環", "氧不是能量，仍需養分提供可轉換化學能"], 3, ["氧攝取不會改變器官種類。", "養分具有供能與構造等多種角色。", "正常吸氧需要循環配合而非停止循環。", "高強度需要氧與養分共同支持反應。"], ["細胞呼吸需要氧，也需要含化學能的養分，兩者不能互相取代。", "「氧不是能量，仍需養分提供可轉換化學能」指出長期限制，避免把高吸氧量誤認為能量來源充足。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S061", "BIO_R4_S061", "cell-metabolism-data",
  { title: "肌肉細胞活動資料", text: "研究者測量同一批肌肉細胞在休息與收縮狀態下，每分鐘葡萄糖消耗、氧消耗、二氧化碳產生與可用能量指標。其他培養條件相同。", note: "指標數值只供比較兩種狀態，不代表人體完整代謝量。" },
  { summary: "表格比較休息與收縮肌肉細胞的物質消耗、產物與能量指標。", colorIndependent: true, dataFallback: { columns: ["狀態", "葡萄糖消耗", "氧消耗", "二氧化碳產生", "能量指標"], rows: [["休息", "2", "3", "3", "4"], ["收縮", "7", "10", "10", "13"]] } },
  [
    question("BIO_R4_SQ_061_01", "BIO_R4_S061", "standard", "收縮狀態相較休息，哪項變化有直接資料支持？", ["葡萄糖與氧消耗都增加", "葡萄糖完全不消耗", "二氧化碳產生降為零", "能量指標下降"], 0, ["葡萄糖2到7、氧3到10，兩者都上升。", "收縮狀態葡萄糖消耗為7而非零。", "二氧化碳由3增到10。", "能量指標由4升到13。"], ["逐欄比較可見兩種反應物消耗均在收縮時增加。", "「葡萄糖與氧消耗都增加」同時符合兩欄資料，其他選項都與數值方向相反。"]),
    question("BIO_R4_SQ_061_02", "BIO_R4_S061", "advanced", "哪項解釋最能連結收縮與能量指標變化？", ["肌肉收縮不需要能量", "細胞呼吸加快以支持肌肉收縮", "氧直接變成能量指標", "二氧化碳是主要燃料"], 1, ["收縮狀態能量指標明顯較高。", "耗糖耗氧與產二氧化碳都支持代謝加快。", "氧是反應物而不是能量本身。", "二氧化碳是反應產物而非燃料。"], ["四欄資料共同呈現細胞呼吸速率提高並供應收縮需求。", "「細胞呼吸加快以支持肌肉收縮」能整合反應物、產物與能量，沒有混淆物質角色。"]),
    question("BIO_R4_SQ_061_03", "BIO_R4_S061", "transfer", "若收縮組葡萄糖不足，最合理預測為何？", ["肺泡數量立即增加", "二氧化碳變成葡萄糖", "可轉換能量來源受限，能量指標可能下降", "細胞不再需要氧與養分"], 2, ["細胞培養養分不會立即改變肺泡數量。", "二氧化碳不會自動逆轉成全部葡萄糖。", "反應物不足會限制細胞呼吸與能量產生。", "活細胞仍有基本代謝需求。"], ["資料顯示葡萄糖消耗與較高能量指標並行，缺糖會限制反應。", "「可轉換能量來源受限，能量指標可能下降」是依反應物角色作出的有限預測，沒有跨到無關構造。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S062", "BIO_R4_S062",
  ["比較吸入氣與呼出氣中氧、二氧化碳、水氣與氮的相對差異。", "由氣體組成資料連結肺部交換，避免把呼出氣誤認為完全沒有氧。"],
  [
    { id: "BIO_R4_L_S062_SEC_01", title: "呼出氣仍含氧", content: "吸入氣中的部分氧在肺泡進入血液，但不會每次都被完全取走，因此呼出氣仍含相當比例的氧。比較時應說呼出氣氧通常較少，不說完全沒有氧。" },
    { id: "BIO_R4_L_S062_SEC_02", title: "呼出氣二氧化碳較多", content: "細胞產生的二氧化碳由血液送到肺泡，再隨呼氣排出，所以呼出氣中的二氧化碳比例通常高於吸入氣。這是交換與細胞代謝相連的結果。" },
    { id: "BIO_R4_L_S062_SEC_03", title: "水氣與溫度會變化", content: "空氣通過濕潤呼吸道與肺泡後，呼出氣水氣通常較多且接近體溫。環境濕度不同會影響差異，不能把每次水氣數值視為固定不變。" },
    { id: "BIO_R4_L_S062_SEC_04", title: "氮變化通常較小", content: "氮在人體呼吸交換中不是主要被利用或產生的氣體，因此吸入與呼出氣的氮比例通常變化較小。比例仍可能因氧、二氧化碳與水氣變化而略有差異。" },
  ],
  [
    { id: "BIO_R4_L_S062_EX_01", prompt: "吸入氣氧21%、呼出氣16%，能否說呼出氣沒有氧？", steps: ["讀出呼出氣氧仍為16%。", "區分較少與完全沒有。"], answer: "不能，呼出氣仍含氧", why: "呼出氣氧比例比吸入氣低，表示部分氧進入血液，但16%明顯不是零，因此不能用完全沒有描述。" },
    { id: "BIO_R4_L_S062_EX_02", prompt: "呼出氣二氧化碳較多，來源最可能為何？", steps: ["追蹤細胞呼吸產生的二氧化碳。", "連結血液運送與肺泡交換。"], answer: "細胞代謝產生後由血液送到肺排出", why: "二氧化碳由組織細胞產生，進入血液並在肺泡移入氣體，因而使呼出氣比例較吸入氣高。" },
    { id: "BIO_R4_L_S062_EX_03", prompt: "吸入與呼出氣氮比例接近，表示什麼？", steps: ["比較同一氣體兩組數值。", "判斷氮是否為主要交換氣體。"], answer: "氮通常不是人體呼吸主要交換氣體", why: "氮在肺部沒有像氧與二氧化碳那樣明顯的淨交換，因此兩種氣體樣本中的比例通常相近。" },
  ],
  [
    { belief: "呼出氣完全不含氧。", whyWrong: "肺泡只取走吸入氧的一部分，呼出氣仍保留相當比例氧。", correction: "描述為呼出氣氧較少，不使用氧為零的絕對說法。" },
    { belief: "呼出氣全部都是二氧化碳。", whyWrong: "呼出氣仍以氮、氧等成分為主，二氧化碳只是比例增加。", correction: "比較各成分比例，不把增加誇大成占據全部氣體。" },
    { belief: "吸入與呼出氣所有成分都完全不同。", whyWrong: "兩者含有多種相同氣體，主要差別在部分成分比例。", correction: "逐項比較氧、二氧化碳、水氣與氮，不把組成說成完全替換。" },
    { belief: "呼出氣水氣在任何環境都固定同一數值。", whyWrong: "呼吸道濕潤會增加水氣，但環境濕度與測量條件仍會影響數值。", correction: "用通常較多描述趨勢，精確數值需依當次測量資料。" },
  ],
  [
    { prompt: "呼出氣是否仍含有氧？", answer: "含有", reason: "人體只利用吸入氧的一部分，呼出氣中的氧比例仍明顯高於零。" },
    { prompt: "呼出氣哪種代謝氣體通常較多？", answer: "二氧化碳", reason: "細胞產生的二氧化碳由血液送到肺泡並隨呼氣排出。" },
    { prompt: "吸入與呼出氣哪種氣體比例通常較接近？", answer: "氮", reason: "氮不是人體呼吸主要利用或產生的氣體，因此變化通常較小。" },
  ],
));

questions.push(
  question("BIO_R4_Q_062_01", "BIO_R4_S062", "foundation", "比較吸入氣與呼出氣，呼出氣中的氧通常如何？", ["比例較低但仍存在", "完全等於零", "比例一定加倍", "全部變成氮"], 0, ["部分氧進血，但呼出氣仍保留氧。", "人體不會在一次呼吸取走全部氧。", "呼出氣氧通常較低而非加倍。", "氧也不會因呼吸全部轉成氮。"], ["呼吸交換取走部分氧，因此應描述呼出氣氧較少但非零。", "「比例較低但仍存在」保留相對差異，「完全等於零」、「比例一定加倍」、「全部變成氮」皆是過度或錯誤轉換。"]),
  question("BIO_R4_Q_062_02", "BIO_R4_S062", "foundation", "呼出氣中哪一種由細胞代謝產生的氣體，比例通常比吸入氣明顯較高？", ["氧氣", "二氧化碳", "氮氣", "氦氣"], 1, ["氧進入血液後呼出比例通常降低。", "細胞產生的二氧化碳由肺排出而增加。", "氮比例通常變化較小。", "人體不會代謝產生大量氦氣。"], ["組織二氧化碳經血液到肺泡，造成呼出氣比例上升。", "「二氧化碳」符合代謝與交換路徑，其他氣體沒有此增加來源。"]),
  question("BIO_R4_Q_062_03", "BIO_R4_S062", "foundation", "吸入與呼出氣中，哪種氣體比例通常變化較小？", ["氧氣", "二氧化碳", "氮氣", "水蒸氣"], 2, ["氧被血液吸收，比例會有明顯下降。", "二氧化碳由血液排入肺泡，比例增加。", "氮不是主要利用或產生氣體。", "水氣受呼吸道濕潤而常增加。"], ["氮沒有像氧和二氧化碳那樣大量淨交換，因此前後較接近。", "「氮氣」符合人體氣體交換角色，其他成分都有較明顯變化。"]),
  question("BIO_R4_Q_062_04", "BIO_R4_S062", "standard", "關於呼出氣的敘述，何者正確？", ["只含二氧化碳", "完全不含氮", "水氣一定比所有氣體多", "仍含氧，且二氧化碳通常較吸入氣多"], 3, ["呼出氣還含氮、氧與水氣等。", "氮仍是呼出氣重要成分。", "水氣不會因此超過所有主要氣體。", "此項正確描述兩種主要差異。"], ["呼出氣不是單一氣體，而是成分比例與吸入氣不同的混合氣體。", "「仍含氧，且二氧化碳通常較吸入氣多」同時避免氧為零與二氧化碳全占的錯誤。"]),
  question("BIO_R4_Q_062_05", "BIO_R4_S062", "standard", "吸入氧21%、呼出氧16%，最直接支持哪項結論？", ["部分氧進入血液，但呼出氣仍有氧", "人體完全未利用氧", "呼出氣全部是二氧化碳", "氮在呼出氣中消失"], 0, ["氧比例下降且非零，符合部分交換。", "比例下降反駁完全未利用。", "氧仍有16%，不能說全部是二氧化碳。", "資料沒有顯示氮消失。"], ["21降到16表示有一部分氧離開肺泡氣，但仍保留相當比例。", "「部分氧進入血液，但呼出氣仍有氧」完整對應兩個數值，不加入未測的其他氣體結論。"]),
  question("BIO_R4_Q_062_06", "BIO_R4_S062", "standard", "呼出氣二氧化碳增加，最合理來源為何？", ["鼻毛製造", "細胞呼吸產生後由血液運到肺", "胃把食物直接變成氣體", "外界氮全部轉換"], 1, ["鼻毛主要攔截顆粒而不製造二氧化碳。", "細胞代謝與肺部交換形成完整來源路徑。", "胃不會把食物直接轉成呼出氣。", "氮也不會在人體中全部轉成二氧化碳。"], ["二氧化碳先在組織細胞產生，再經血液與肺泡進入呼出氣。", "「細胞呼吸產生後由血液運到肺」符合跨系統路徑，其他選項缺乏化學與器官依據。"]),
  question("BIO_R4_Q_062_07", "BIO_R4_S062", "standard", "冬天呼氣可在冷玻璃形成水霧，最能說明什麼？", ["呼出氣沒有氧", "肺泡只含液態水", "呼出氣含有較多水蒸氣", "氮已完全消失"], 2, ["水霧不能證明氧不存在。", "肺泡需含空氣而非只含液水。", "水蒸氣遇冷凝結可形成小水滴。", "水霧也與氮是否消失無關。"], ["呼吸道使呼出氣較濕，水蒸氣遇冷表面可凝結成霧。", "「呼出氣含有較多水蒸氣」能解釋觀察，其他敘述都超出水霧證據。"]),
  question("BIO_R4_Q_062_08", "BIO_R4_S062", "advanced", "兩份氣體樣本中，甲氧較高且二氧化碳較低，甲較可能是什麼？", ["只有細胞產物", "尿液中的氣泡", "胃內氣體", "吸入氣"], 3, ["細胞產物會使二氧化碳來源增加。", "尿液氣泡不是正常比較樣本。", "胃內氣體也不是肺換氣標準樣本。", "吸入氣通常氧較高、二氧化碳較低。"], ["同時使用氧和二氧化碳兩項相對差異，可將甲判為吸入氣。", "「吸入氣」符合交換前組成，其餘樣本沒有此標準關係。"]),
  question("BIO_R4_Q_062_09", "BIO_R4_S062", "advanced", "呼出氣與吸入氣氮比例接近，最合理原因為何？", ["氮不是人體呼吸主要利用或產生的氣體", "氮會全部進入細胞供能", "氮在肺泡變成葡萄糖", "氮只存在胃中"], 0, ["沒有明顯淨交換使前後比例較接近。", "氮不是人體主要供能反應氣體。", "肺泡不會把氮合成葡萄糖。", "氮廣泛存在空氣而非只在胃。"], ["氣體比例變化取決於人體是否大量利用或產生，氮兩者皆少。", "「氮不是人體呼吸主要利用或產生的氣體」能解釋前後接近，其他選項錯置氮的角色。"]),
  question("BIO_R4_Q_062_10", "BIO_R4_S062", "advanced", "為何不同環境測得的呼出氣水氣差異可能不同？", ["水氣不是物質", "吸入空氣濕度與測量條件也會影響", "肺泡在乾燥時變成腎臟", "氧會無限轉成水"], 1, ["水氣是氣態水，具有可測量含量。", "環境背景不同會改變前後比較。", "乾燥不會改變器官種類。", "呼吸不會使氧無限轉為水。"], ["呼吸道濕潤是共同趨勢，但起始濕度與溫度仍影響數值。", "「吸入空氣濕度與測量條件也會影響」說明為何不應把水氣比例當固定常數。"]),
  question("BIO_R4_Q_062_11", "BIO_R4_S062", "transfer", "人工呼吸能提供受助者部分氧氣，最直接依據是什麼？", ["呼出氣只有二氧化碳", "氮會變成氧", "呼出氣仍保留相當比例氧氣", "水氣可以完全取代氧"], 2, ["呼出氣不是只含二氧化碳。", "人體不會把氮轉成大量氧。", "未被利用的氧仍存在於呼出氣。", "水氣無法取代細胞所需氧。"], ["呼出氣氧比例低於吸入氣但仍明顯高於零，可提供部分氧。", "「呼出氣仍保留相當比例氧氣」直接連結組成差異與生活應用，其他選項錯誤。"]),
  question("BIO_R4_Q_062_12", "BIO_R4_S062", "transfer", "結合呼出氣二氧化碳較多及已知運送路徑，下列哪個結論仍不能成立？", ["細胞可能產生二氧化碳", "肺可排出二氧化碳", "血液參與運送二氧化碳", "呼出氣完全不含氧"], 3, ["二氧化碳增加與細胞產生相符。", "呼出氣增加也支持肺排出。", "由組織到肺需要循環運輸。", "二氧化碳增加不代表氧為零。"], ["已知路徑可支持二氧化碳的來源與運送，卻不能推成呼出氣沒有氧。", "「呼出氣完全不含氧」超出資料且違反呼出氣仍含氧的事實。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S062", "BIO_R4_S062", "gas-composition",
  { title: "吸入與呼出氣分析", text: "同一受試者在安靜狀態下採集吸入氣與呼出氣樣本，儀器測得氧、二氧化碳及氮的體積百分比。水氣未列入表中，因此三項加總可能因四捨五入與其他微量氣體而不完全相同。", note: "數值為原創教學資料，只代表本次測量。" },
  { summary: "表格比較吸入與呼出氣的氧、二氧化碳與氮比例。", colorIndependent: true, dataFallback: { columns: ["樣本", "氧", "二氧化碳", "氮"], rows: [["吸入氣", "21%", "0.04%", "78%"], ["呼出氣", "16%", "4%", "79%"]] } },
  [
    question("BIO_R4_SQ_062_01", "BIO_R4_S062", "standard", "依表格，哪種氣體由吸入到呼出比例明顯下降？", ["三者都下降", "二氧化碳", "氮氣", "氧氣"], 3, ["二氧化碳與氮都未下降。", "二氧化碳由0.04%升到4%。", "氮由78%到79%，沒有下降。", "氧由21%降到16%，下降明顯。"], ["逐欄比較，只有氧的數值由較高變較低。", "「氧氣」可由表格直接讀出，也符合部分氧進入血液。"]),
    question("BIO_R4_SQ_062_02", "BIO_R4_S062", "advanced", "哪項敘述最符合表中呼出氣？", ["仍有16%氧且二氧化碳較吸入氣多", "完全沒有氧", "全部都是氮", "二氧化碳比氧更多"], 0, ["此項同時符合氧與二氧化碳兩欄。", "呼出氣氧欄明確為16%。", "氮為79%而不是全部。", "二氧化碳4%仍低於氧16%。"], ["需要同時讀取兩種氣體，呼出氣保留氧且二氧化碳增加。", "「仍有16%氧且二氧化碳較吸入氣多」完整符合數字，其他選項使用完全、全部或錯誤大小比較。"]),
    question("BIO_R4_SQ_062_03", "BIO_R4_S062", "transfer", "若另一人呼出氣氧為17%，可否說本表錯誤？", ["可以，所有人必須固定16%", "不能，個體與測量條件可不同，本表只代表一次測量", "可以，呼出氣不能含氧", "不能，因為17%等於零"], 1, ["表格已限定只代表本次測量。", "小幅差異不否定相對趨勢。", "呼出氣本來就會保留氧。", "17%明顯不等於零。"], ["生理數值可受活動、換氣與測量條件影響，不必人人完全相同。", "「不能，個體與測量條件可不同，本表只代表一次測量」保留資料適用範圍，也不否定呼出氧低於吸入氣的概念。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S063", "BIO_R4_S063",
  ["由運動前後呼吸頻率與換氣量資料描述變化。", "連結活動能量需求、氧供應與二氧化碳排出，並限制資料推論範圍。"],
  [
    { id: "BIO_R4_L_S063_SEC_01", title: "活動時呼吸常加快加深", content: "肌肉活動增加時，細胞呼吸需求提高，呼吸頻率與每次呼吸深度常增加，使每分鐘換氣量上升。只看頻率仍不一定能知道總換氣量，還需考慮每次氣量。" },
    { id: "BIO_R4_L_S063_SEC_02", title: "氧供與二氧化碳排出", content: "換氣增加可更新肺泡氣，協助更多氧進入血液，並讓細胞產生的二氧化碳較快由肺排出。呼吸變快不是肺在製造能量，而是在支持細胞代謝。" },
    { id: "BIO_R4_L_S063_SEC_03", title: "運動後逐漸恢復", content: "運動停止後，呼吸頻率通常不會瞬間回到休息值，而是隨身體需求下降逐步恢復。不同人的體能、強度與環境不同，恢復時間也可能不同。" },
    { id: "BIO_R4_L_S063_SEC_04", title: "資料解讀先描述再解釋", content: "判讀表格先比較各時間點數值，描述上升、最高與下降，再用細胞能量需求提出解釋。單一個案只能支持該次紀錄，不應直接宣稱所有人在任何運動中數值相同。" },
  ],
  [
    { id: "BIO_R4_L_S063_EX_01", prompt: "休息12次、運動28次、恢復18次，哪時呼吸頻率最高？", steps: ["比較三個每分鐘次數。", "找出最大值28所對應狀態。"], answer: "運動時", why: "三個觀察值中28最大，顯示該受試者運動時呼吸頻率高於休息與恢復；結論限於本次資料。" },
    { id: "BIO_R4_L_S063_EX_02", prompt: "頻率相同但每次呼吸量增加，總換氣量會如何？", steps: ["使用每分鐘換氣量與頻率、每次氣量的關係。", "保持頻率固定只比較每次氣量。"], answer: "增加", why: "每分鐘呼吸次數相同時，每次吸入更多空氣會使一分鐘總氣量增加，因此不能只用頻率判斷換氣。" },
    { id: "BIO_R4_L_S063_EX_03", prompt: "運動後五分鐘仍高於休息值，能否說資料錯誤？", steps: ["比較運動停止與生理恢復是否同時完成。", "考慮需求可能逐步下降。"], answer: "不能", why: "運動停止後身體仍需調整氧供、二氧化碳與代謝狀態，呼吸可逐步恢復，不必立即等於休息值。" },
  ],
  [
    { belief: "呼吸頻率增加就必定代表每次呼吸更深。", whyWrong: "頻率與每次氣量是兩個可分別變化的指標，需要各自測量。", correction: "同時查看每分鐘次數與每次氣量，必要時再計算總換氣量。" },
    { belief: "運動時呼吸加快是肺在製造能量。", whyWrong: "能量由肌肉等細胞呼吸轉換，肺部換氣負責支持氣體供應。", correction: "把呼吸變化連到氧輸入與二氧化碳排出，不把肺當能量來源。" },
    { belief: "停止運動後呼吸一定立刻回復。", whyWrong: "身體代謝與氣體需求需時間調整，恢復通常是逐步過程。", correction: "依多個恢復時間點判讀趨勢，不只比較停止瞬間。" },
    { belief: "一人的運動數據可以代表所有人固定數值。", whyWrong: "強度、體能與環境都可能造成個體與次數差異。", correction: "保留資料來源限制，以趨勢描述而非宣稱普遍固定數值。" },
  ],
  [
    { prompt: "運動時呼吸頻率通常如何變化？", answer: "增加", reason: "活動細胞對氧需求與二氧化碳排出需求提高，換氣常加快。" },
    { prompt: "只看呼吸頻率能否確定總換氣量？", answer: "不能", reason: "每分鐘總換氣量還受到每次呼吸氣量大小的共同影響。" },
    { prompt: "運動後呼吸為何逐步恢復？", answer: "代謝與氣體需求逐漸下降", reason: "停止活動後身體仍需一段時間調整，呼吸不必瞬間回到休息值。" },
  ],
));

questions.push(
  question("BIO_R4_Q_063_01", "BIO_R4_S063", "foundation", "一般而言，運動時呼吸頻率相較休息時常如何變化？", ["增加", "必定變成零", "完全不變", "無限下降"], 0, ["活動需求提高時呼吸次數常增加。", "運動時仍需持續換氣，不會成零。", "多數情況會因需求而調整。", "無限下降也不符合氧供需求。"], ["肌肉活動增加氧需求與二氧化碳產生，呼吸頻率通常上升。", "「增加」符合一般趨勢，其他選項使用絕對且與生理需求相反。"]),
  question("BIO_R4_Q_063_02", "BIO_R4_S063", "foundation", "每分鐘呼吸次數稱為哪一種資料？", ["每次氣量", "呼吸頻率", "血糖濃度", "肺泡面積"], 1, ["每次氣量是單次吸入或呼出的體積。", "每分鐘次數正是呼吸頻率的定義。", "血糖是血液中的養分濃度。", "肺泡面積屬構造資料。"], ["題幹的單位是次數除以時間，直接對應呼吸頻率。", "「呼吸頻率」符合測量定義，其他指標的物理量與單位不同。"]),
  question("BIO_R4_Q_063_03", "BIO_R4_S063", "foundation", "運動時呼吸加快，最直接有助排出哪種細胞代謝氣體？", ["氧氣", "氮氣", "二氧化碳", "氦氣"], 2, ["氧主要由外界吸入並供細胞利用。", "氮不是細胞呼吸主要產物。", "二氧化碳由細胞產生並經肺排出。", "人體也不會產生大量氦氣。"], ["運動時細胞呼吸加快，二氧化碳產生增加，需要更快排出。", "「二氧化碳」符合細胞到血液再到肺的物質路徑。"]),
  question("BIO_R4_Q_063_04", "BIO_R4_S063", "standard", "判斷每分鐘換氣量除了呼吸頻率，還需知道什麼？", ["牙齒數量", "食物甜度", "尿液顏色", "每次呼吸氣量"], 3, ["牙齒數量不決定肺換氣量。", "食物甜度也不是通氣測量。", "尿液顏色與單次呼吸體積無關。", "頻率乘每次氣量才能估計總換氣。"], ["同樣頻率下，深呼吸與淺呼吸的一分鐘總氣量不同。", "「每次呼吸氣量」是計算每分鐘換氣量不可缺少的第二個指標。"]),
  question("BIO_R4_Q_063_05", "BIO_R4_S063", "standard", "休息14次、跑步32次、恢復20次，哪項描述正確？", ["跑步時呼吸頻率最高", "休息時頻率最高", "恢復時比跑步高", "三個數值相同"], 0, ["32是三個數值中的最大值。", "休息14低於另外兩個數值。", "恢復20仍低於跑步32。", "14、32、20明顯不同。"], ["直接比較每分鐘次數，跑步狀態的32最高。", "「跑步時呼吸頻率最高」只描述資料，不推論所有人跑步都必須等於32次。"]),
  question("BIO_R4_Q_063_06", "BIO_R4_S063", "standard", "運動後三分鐘呼吸仍高於休息值，最合理解釋為何？", ["資料一定錯誤", "身體氣體與代謝需求仍在逐步恢復", "肺泡已全部消失", "氧不再參與細胞呼吸"], 1, ["恢復非瞬間完成，數值可合理偏高。", "停止運動後身體仍需一段調整時間。", "呼吸偏高不表示肺泡消失。", "氧仍參與多數人體細胞呼吸。"], ["運動停止和生理恢復不是同一瞬間，呼吸可逐步下降。", "「身體氣體與代謝需求仍在逐步恢復」符合時間序列，其他選項否定資料或基本構造。"]),
  question("BIO_R4_Q_063_07", "BIO_R4_S063", "standard", "運動時換氣增加主要如何支持肌肉？", ["直接在肺製造葡萄糖", "把二氧化碳變成蛋白質", "協助氧進血並排出較多二氧化碳", "使肌肉完全不需養分"], 2, ["肺不負責製造葡萄糖。", "換氣不會把氣體轉成蛋白質。", "更新肺泡氣可支持雙向交換。", "肌肉仍需養分提供化學能。"], ["換氣的直接功能是更新肺泡氧與二氧化碳，間接支持肌肉代謝。", "「協助氧進血並排出較多二氧化碳」正確描述氣體供排，不把肺誤當能量或養分來源。"]),
  question("BIO_R4_Q_063_08", "BIO_R4_S063", "advanced", "兩人頻率同為24次，但甲每次氣量較大，可推論什麼？", ["兩人總換氣量必定相同", "乙一定沒有肺泡", "甲一定不需氧", "甲每分鐘換氣量可能較大"], 3, ["每次氣量不同會影響總量。", "頻率資料不能證明肺泡不存在。", "換氣量較大不表示不需要氧。", "頻率相同時單次量較大會提高總量。"], ["總換氣量同時取決於頻率與每次氣量，不能只看次數。", "「甲每分鐘換氣量可能較大」用可能表述合理推論，並保留實際測量誤差。"]),
  question("BIO_R4_Q_063_09", "BIO_R4_S063", "advanced", "運動強度逐級增加，呼吸頻率也逐級上升，最保守結論為何？", ["本次資料中兩者呈同向變化", "呼吸頻率造成所有肌肉生長", "任何人數值都必定相同", "強度越高氧濃度必為零"], 0, ["此項忠實描述觀察到的共同趨勢。", "相關變化不能證明所有肌肉生長因果。", "個體差異使數值不會人人固定。", "呼吸增加不表示氧濃度變零。"], ["單次資料最先支持的是同向關係，因果仍需控制實驗檢驗。", "「本次資料中兩者呈同向變化」沒有超出資料範圍，其他選項皆過度推論。"]),
  question("BIO_R4_Q_063_10", "BIO_R4_S063", "advanced", "要比較運動前後呼吸變化，哪個設計較可靠？", ["前後使用不同計時長度卻不換算", "同一人、相同計時方法並重複測量", "只憑感覺說很喘", "運動前後換不同受試者"], 1, ["時間不同且不換算會失去可比性。", "同人同方法可降低個體與程序差異。", "主觀感覺缺少量化標準。", "換人會把個體差異混入前後比較。"], ["前後比較需控制受試者與測量方法，並用重複檢查穩定性。", "「同一人、相同計時方法並重複測量」最能把差異合理連結到運動狀態。"]),
  question("BIO_R4_Q_063_11", "BIO_R4_S063", "transfer", "爬樓梯後說話較喘，最合理的生物解釋為何？", ["肺開始消化澱粉", "細胞停止產生二氧化碳", "活動需求提高使換氣增加", "所有血液離開身體"], 2, ["肺不進行澱粉化學消化。", "活動時二氧化碳產生通常增加。", "肌肉耗能增加會提高氧供與排碳需求。", "循環血量不會因爬樓梯全部離體。"], ["爬樓梯提高肌肉細胞呼吸需求，呼吸加快加深以支持氣體交換。", "「活動需求提高使換氣增加」連結生活觀察與生理機制，其他選項明顯錯誤。"]),
  question("BIO_R4_Q_063_12", "BIO_R4_S063", "transfer", "若運動後頻率下降但每次呼吸更深，總換氣量如何判斷？", ["只看頻率即可確定下降", "一定變成零", "一定無限增加", "需同時計算頻率與每次氣量"], 3, ["單次氣量增加可能抵銷頻率下降。", "仍在呼吸不會使總量必為零。", "資料也不能支持無限增加。", "兩個因素共同決定每分鐘總量。"], ["頻率與深度朝相反方向變化時，無法只靠其中一項下結論。", "「需同時計算頻率與每次氣量」指出需要的完整計算資料，是唯一可靠判斷。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S063", "BIO_R4_S063", "exercise-breathing-log",
  { title: "跑步前後呼吸紀錄", text: "同一名學生先安靜坐五分鐘，再慢跑六分鐘，停止後每隔三分鐘測量呼吸頻率與每次呼吸氣量。每分鐘換氣量為兩者相乘所得，所有測量使用相同儀器。", note: "資料只代表這名學生本次活動，不用來診斷健康狀況。" },
  { summary: "表格列出休息、跑步與恢復階段的呼吸頻率、每次氣量和每分鐘換氣量。", colorIndependent: true, dataFallback: { columns: ["狀態", "頻率", "每次氣量", "每分鐘換氣量"], rows: [["休息", "12次", "0.5公升", "6公升"], ["跑步", "30次", "1.2公升", "36公升"], ["恢復3分鐘", "20次", "0.8公升", "16公升"], ["恢復6分鐘", "14次", "0.6公升", "8.4公升"]] } },
  [
    question("BIO_R4_SQ_063_01", "BIO_R4_S063", "standard", "哪個狀態的每分鐘換氣量最高？", ["恢復3分鐘", "休息", "跑步", "恢復6分鐘"], 2, ["恢復3分鐘為16公升，低於跑步。", "休息時只有6公升。", "跑步時36公升是表中最大值。", "恢復6分鐘8.4公升也較低。"], ["逐列比較每分鐘換氣量，36公升最大且對應跑步。", "答案直接來自表格，不需只用呼吸頻率另行猜測。"]),
    question("BIO_R4_SQ_063_02", "BIO_R4_S063", "advanced", "停止跑步後，換氣量呈現何種趨勢？", ["持續增加", "三個時間完全相同", "立刻降為零", "由36降到16再降到8.4"], 3, ["恢復數值沒有持續增加。", "36、16與8.4並不相同。", "停止運動後仍持續呼吸。", "兩個恢復點依序下降，符合逐步恢復。"], ["時間序列顯示跑步後換氣量逐步下降，而非瞬間回到休息值。", "「由36降到16再降到8.4」精確引用三個數值，其他選項與資料衝突。"]),
    question("BIO_R4_SQ_063_03", "BIO_R4_S063", "transfer", "若只記錄頻率而不測每次氣量，會失去哪項資訊？", ["無法準確比較每分鐘總換氣量", "跑步時間是否存在", "受試者姓名", "肺泡是否含任何氣體"], 0, ["總量還需頻率乘以每次氣量。", "活動時間可另外由程序記錄。", "姓名與是否測每次氣量無關。", "有呼吸並不表示肺泡完全無氣。"], ["表格顯示每分鐘換氣量由兩個指標共同決定，缺一無法完整計算。", "「無法準確比較每分鐘總換氣量」指出實際資訊缺口，沒有將測量不足誇大成肺泡不存在。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S064", "BIO_R4_S064",
  ["串連呼吸系統、循環系統與細胞呼吸在能量供應中的分工", "依活動前後的呼吸與心跳資料，推論氧氣運送及能量需求的改變"],
  [
    { id: "BIO_R4_L_S064_SEC_01", title: "呼吸系統交換氣體", content: "空氣進入肺泡後，氧氣由肺泡擴散進入微血管，血液中的二氧化碳則擴散到肺泡並隨呼氣排出。呼吸系統負責取得氧氣與排除部分代謝廢物，但不直接把氧氣送到全身每一個細胞。" },
    { id: "BIO_R4_L_S064_SEC_02", title: "循環系統負責運送", content: "進入肺部微血管的氧氣會隨血液流回心臟，再由心臟送往全身。血液也把消化吸收的養分送到細胞，並將細胞產生的二氧化碳運回肺部，因此心臟、血管與血液是肺和細胞之間的運輸橋梁。" },
    { id: "BIO_R4_L_S064_SEC_03", title: "細胞呼吸釋放能量", content: "細胞利用氧氣分解養分，釋放可供生命活動使用的能量，並產生二氧化碳和水。肺部的氣體交換不等於細胞呼吸；前者發生在肺泡與微血管之間，後者發生在細胞內。" },
    { id: "BIO_R4_L_S064_SEC_04", title: "活動時的協調反應", content: "運動時肌肉細胞需要較多能量，氧氣消耗與二氧化碳產生通常增加。呼吸加快有助於肺部交換更多氣體，心跳加快則有助於血液更快運送氧氣與養分、帶走二氧化碳；兩套系統共同回應細胞需求。" },
  ],
  [
    { id: "BIO_R4_L_S064_EX_01", prompt: "跑步時，呼吸與心跳為何常同時加快？", steps: ["先判斷運動中的肌肉細胞需要較多能量", "再連結氧氣取得、血液運送與細胞呼吸"], answer: "為增加氧氣交換與運送，並加速帶走二氧化碳", why: "肌肉細胞活動增強時，細胞呼吸對氧氣與養分的需求上升；呼吸加快提高肺部氣體交換量，心跳加快提高血液運輸速率，兩者共同支持能量供應。" },
    { id: "BIO_R4_L_S064_EX_02", prompt: "肺部交換正常，但流向腿部的血流大幅減少，腿部細胞最先受到哪種限制？", steps: ["確認肺部仍能讓氧氣進入血液", "判斷血流減少會限制氧氣與養分抵達腿部"], answer: "腿部細胞取得氧氣與養分的速率降低", why: "氧氣雖已在肺部進入血液，仍必須靠循環系統送到腿部；局部血流減少會讓氧氣與養分供應不足，也使二氧化碳移除變慢，因而限制細胞釋能。" },
    { id: "BIO_R4_L_S064_EX_03", prompt: "某人的吸入氧氣量增加，但細胞無法利用氧氣，是否能因此正常增加能量供應？", steps: ["區分取得氧氣與利用氧氣兩個階段", "檢查細胞呼吸是否能順利進行"], answer: "不能，細胞無法利用氧氣便不能正常增加有氧釋能", why: "呼吸系統取得氧氣只是供能鏈的一環，氧氣還要經血液運到細胞並參與細胞呼吸；若細胞無法利用氧氣，即使吸入較多也不能轉成相應的能量供應。" },
  ],
  [
    { belief: "氧氣在肺泡中直接轉變成細胞可用的能量", whyWrong: "肺泡只進行氣體交換，不會把氧氣轉變成生命活動可用的能量。", correction: "氧氣先由肺泡進入血液，再運到細胞參與細胞呼吸，養分中的能量才會被釋放。" },
    { belief: "心跳加快只為了把二氧化碳送到肌肉", whyWrong: "二氧化碳是肌肉細胞產生後需要帶走的物質，不是送入肌肉的原料。", correction: "心跳加快可增進氧氣與養分送達肌肉，也能加速把肌肉產生的二氧化碳運走。" },
    { belief: "只要呼吸次數增加，全身細胞一定能取得足夠氧氣", whyWrong: "氧氣進入肺部後仍需循環運送，呼吸加快不能補償嚴重的血流障礙。", correction: "細胞獲得氧氣需要氣體交換與循環運送都正常，任一環節受阻都可能造成供應不足。" },
    { belief: "肺部氣體交換和細胞呼吸是發生在同一處的同一反應", whyWrong: "兩者的地點與功能不同，肺泡交換氣體，細胞呼吸則分解養分並釋放能量。", correction: "肺部先讓氧氣進入血液，循環再送到細胞，細胞才利用氧氣進行釋能反應。" },
  ],
  [
    { prompt: "氧氣從外界到達手臂細胞，必須依序經過哪兩項主要功能？", answer: "肺部氣體交換與血液循環運送", reason: "氧氣先由肺泡擴散進入血液，再由心臟推動血液流向手臂，才能抵達當地細胞。" },
    { prompt: "運動時細胞產生較多二氧化碳，呼吸和循環如何配合？", answer: "血液加速運回肺部，再由呼氣排出", reason: "循環系統將肌肉產生的二氧化碳帶到肺部，呼吸系統再把它交換至肺泡並排出體外。" },
    { prompt: "為何不能用心跳加快單獨證明肺部氣體交換量增加？", answer: "心跳反映循環運輸，未直接量到肺部氣體交換", reason: "心跳增加只能顯示血液運送可能加快，仍需呼吸量或氣體濃度資料才能判斷肺部交換量。" },
  ],
));

questions.push(
  question("BIO_R4_Q_064_01", "BIO_R4_S064", "foundation", "氧氣由肺泡進入血液後，主要靠哪一系統送到腳部肌肉細胞？", ["循環系統", "消化系統", "神經系統", "排泄系統"], 0, ["心臟推動血液流動，可將氧氣由肺部運送到腳部肌肉細胞。", "消化系統負責分解與吸收養分，不能把肺部氧氣送到肌肉。", "神經系統能傳遞訊息與協調反應，並不承擔氧氣的大量運輸。", "排泄系統移除部分代謝廢物，並非氧氣由肺到肌肉的運送途徑。"], ["先分辨各系統的主要功能，再找出負責連接肺部與全身細胞的運輸系統。", "氧氣進入血液後仍未抵達肌肉，必須由心臟與血管構成的循環系統完成運送。"]),
  question("BIO_R4_Q_064_02", "BIO_R4_S064", "foundation", "細胞利用氧氣分解養分並釋放能量的過程稱為何者？", ["肺部換氣", "細胞呼吸", "血液循環", "小腸吸收"], 1, ["肺部換氣使空氣進出肺，但沒有在細胞內分解養分釋放能量。", "細胞呼吸是在細胞內利用氧氣分解養分並釋放可用能量的過程。", "血液循環負責運送氧氣與養分，本身不等於細胞內的釋能反應。", "小腸吸收讓養分進入體內，尚未完成細胞利用養分釋放能量。"], ["題幹同時出現細胞、氧氣、養分與釋放能量，對應的概念是細胞呼吸。", "肺部換氣與循環提供原料和運輸，真正釋放養分能量的反應發生在細胞內。"]),
  question("BIO_R4_Q_064_03", "BIO_R4_S064", "foundation", "肌肉細胞進行細胞呼吸後，產生的二氧化碳主要先由何者帶走？", ["肺泡內的空氣", "小腸內的食物", "流經肌肉的血液", "皮膚表面的汗液"], 2, ["肺泡空氣可接收血液送來的二氧化碳，卻不會直接流到肌肉細胞旁。", "小腸食物提供可吸收的養分，不能收集肌肉細胞產生的二氧化碳。", "肌肉旁微血管中的血液可接收二氧化碳，再把它運往肺部排出。", "汗液主要含水和少量鹽類，不是肌肉二氧化碳離開細胞的主要途徑。"], ["從肌肉到肺部之間需要運輸媒介，流經組織的血液可先接收二氧化碳。", "二氧化碳不是直接從肌肉跑到肺泡，而是先進入微血管並隨循環回到肺部。"]),
  question("BIO_R4_Q_064_04", "BIO_R4_S064", "standard", "健康學生開始快跑後，呼吸與心跳都加快，最合理的整體解釋為何？", ["胃需要更多空氣協助消化食物", "肺部要把氧氣直接製造成葡萄糖", "心臟要讓肌肉停止產生二氧化碳", "肌肉需較多能量，氣體交換與血液運送因而增強"], 3, ["快跑時主要增加的是肌肉能量需求，不是胃利用空氣進行消化。", "肺部只能交換氧氣與二氧化碳，不能把氧氣直接製造成葡萄糖。", "心跳加快能加速帶走二氧化碳，卻不會使活動中的肌肉停止產生它。", "肌肉能量需求提高，使氧氣取得、血液運送與二氧化碳排除都需加快。"], ["把呼吸和心跳視為協調反應，兩者都在支援活動中肌肉細胞的物質交換與釋能。", "運動不會消除二氧化碳的產生，反而因細胞呼吸增強而需要更快將它運走。"]),
  question("BIO_R4_Q_064_05", "BIO_R4_S064", "standard", "某人肺泡氣體交換正常，但心臟輸出血量大幅降低，最可能出現何種情形？", ["全身細胞取得氧氣的速率下降", "肺泡會立刻停止接觸空氣", "小腸將完全不能分解食物", "細胞不再產生任何二氧化碳"], 0, ["即使氧氣能進入肺部血液，心臟輸出降低仍會減慢氧氣送達全身細胞。", "心臟輸出降低影響血液運送，不代表空氣會立刻無法進出肺泡。", "小腸消化不會只因心臟輸出下降就完全停止，題幹也未提供此證據。", "細胞仍可能進行代謝並產生二氧化碳，只是物質運送與供氧受到限制。"], ["題目設定氣體交換仍正常，因此受阻的環節是氧氣隨血液送往全身的運輸。", "判讀串聯系統時要逐段檢查，肺部取得氧氣並不能取代心臟推動血液的功能。"]),
  question("BIO_R4_Q_064_06", "BIO_R4_S064", "standard", "下列哪一條物質移動路徑最能支持肌肉細胞持續釋放能量？", ["二氧化碳由肺泡送到肌肉", "氧氣由肺泡進血液，再送到肌肉細胞", "養分由肌肉送回小腸，再排出體外", "氧氣由肌肉進血液，再由肺泡吸收"], 1, ["二氧化碳是細胞呼吸產物，主要由肌肉運往肺部而非反向供給肌肉。", "肺泡取得的氧氣經循環送到肌肉，可參與細胞呼吸並支持能量釋放。", "養分通常由小腸吸收後送到肌肉使用，不是由肌肉送回小腸排出。", "氧氣的整體方向應由肺泡到血液再到肌肉，選項所述方向恰好相反。"], ["先找出細胞呼吸需要的原料，再確認物質移動方向是否由取得處通往使用處。", "氧氣在肺部進入血液，之後靠循環抵達肌肉；方向顛倒就不能解釋肌肉釋能。"]),
  question("BIO_R4_Q_064_07", "BIO_R4_S064", "standard", "研究者只量到運動後心跳加快。依此資料，最適當的結論為何？", ["可證明肺泡數量在運動後增加", "可證明血液中的氧氣全部被用完", "顯示循環運送速率可能增加，但未直接測得氣體交換量", "顯示肌肉已停止進行細胞呼吸"], 2, ["心跳資料不能證明肺泡結構數量改變，兩者也沒有這種短期因果關係。", "心跳加快不表示血液氧氣全部耗盡，題目也沒有提供血氧濃度測量。", "心跳反映循環活動可能增強，但肺部交換量仍需呼吸量或氣體資料判斷。", "運動時肌肉通常加強細胞呼吸以供能，不會因心跳加快而停止釋能。"], ["結論不能超過測量範圍；心跳資料可支持循環改變，不能直接證明肺部交換細節。", "若要判定氣體交換量，還需每分鐘通氣量或吸入、呼出氣體濃度等直接證據。"]),
  question("BIO_R4_Q_064_08", "BIO_R4_S064", "advanced", "某藥物不影響肺部與心臟，卻使肌肉細胞無法利用氧氣。服藥後快跑，何者最合理？", ["即使氧氣送達肌肉，細胞仍難以正常增加有氧釋能", "肺泡因此完全無法讓氧氣進入血液", "心臟會因此不再推動任何血液", "小腸會立即停止吸收所有養分"], 0, ["障礙位於細胞利用氧氣的階段，氧氣即使到達也難轉為正常的有氧能量供應。", "題幹說明肺部不受影響，不能推論肺泡完全失去氣體交換功能。", "題幹也排除心臟受影響，細胞利用氧氣受阻不等於血流完全停止。", "肌肉利用氧氣的障礙不會直接使小腸立刻停止吸收所有種類的養分。"], ["沿著供能鏈定位受阻環節：肺部取得與循環運送正常，問題發生在細胞利用氧氣。", "原料送達不代表一定能被使用，細胞呼吸受阻時仍不能正常提升有氧能量供應。"]),
  question("BIO_R4_Q_064_09", "BIO_R4_S064", "advanced", "甲運動後呼吸加快但腿部血流不變；乙呼吸與腿部血流都增加。其他條件相同，何者較能提升腿部供氧？", ["甲，因血流不變可讓氧氣停留更久", "乙，因氧氣交換與送達腿部兩個環節都可能增強", "兩者必定相同，因呼吸次數是唯一因素", "無法比較，因血流與氧氣運送毫無關係"], 1, ["腿部血流不變會限制新增氧氣送達，停留較久也不等於供氧量必然較高。", "乙同時增強肺部取得氧氣與血液送往腿部的能力，較可能提高供氧量。", "供氧不只取決於呼吸次數，還受每次通氣、血氧與局部血流等因素影響。", "血液是氧氣由肺到腿部的主要運輸媒介，因此局部血流與供氧密切相關。"], ["比較串聯流程時，要同時檢查肺部取得與循環送達，兩環節都增強較能支持供氧。", "呼吸加快若沒有相應血流改變，並不能保證額外進入血液的氧氣更快送到腿部。"]),
  question("BIO_R4_Q_064_10", "BIO_R4_S064", "advanced", "運動後量得每分鐘氧氣消耗量與二氧化碳排出量都上升，最能支持哪項推論？", ["肺部把二氧化碳轉換成氧氣", "消化系統停止把養分送入血液", "活動組織的細胞呼吸整體增強", "所有細胞都以完全相同幅度增加活動"], 2, ["人體肺部進行氣體交換，不會把二氧化碳直接轉換成氧氣。", "氧氣消耗與二氧化碳排出上升不能支持消化吸收完全停止的推論。", "細胞利用更多氧氣並產生更多二氧化碳，符合整體細胞呼吸增強的結果。", "整體數據無法證明每一種細胞都以相同幅度改變，活動肌肉通常變化較大。"], ["氧氣是細胞呼吸的重要反應物，二氧化碳是產物，兩者同步改變可支持釋能活動增強。", "整體測量能反映全身趨勢，但不能把平均變化誤認為每個細胞都有完全相同反應。"]),
  question("BIO_R4_Q_064_11", "BIO_R4_S064", "transfer", "登山者在高處每次呼吸取得的氧氣較少，身體卻提高呼吸與心跳速率。此反應最可能有何意義？", ["讓胃部直接從空氣吸收養分", "使肺泡不再需要進行氣體交換", "阻止肌肉細胞產生任何二氧化碳", "增加氧氣取得與運送機會，以維持細胞能量供應"], 3, ["空氣不提供可由胃直接吸收的養分，提高呼吸與心跳也不是為了胃部取食。", "提高呼吸速率正是為增加氣體交換機會，不表示肺泡不再需要交換氣體。", "細胞只要持續代謝仍可能產生二氧化碳，調節反應是加速運走而非完全阻止。", "在每次取得氧氣較少時，提高通氣與循環速率有助於維持氧氣送達細胞。"], ["環境供氧下降時，身體可用提高呼吸和心跳來部分補償每次交換與運送的不足。", "這種補償不能把二氧化碳產生降為零，而是盡量維持細胞呼吸所需的氧氣供應。"]),
  question("BIO_R4_Q_064_12", "BIO_R4_S064", "transfer", "人工裝置可使血液含氧量正常，但病人的血液無法流過手部。最合理的預測為何？", ["手部細胞必定取得更多氧氣，因全身血氧正常", "手部會改由皮膚直接大量吸收空氣中的氧氣", "肺部會把氧氣直接傳送到手部而不經血液", "手部細胞仍可能缺氧，因氧氣無法隨血液送達"], 3, ["全身血氧值不能取代局部循環，血液未抵達便無法把氧氣交給手部細胞。", "人體皮膚不是供應深部組織氧氣的主要呼吸器官，不能補足局部血流中斷。", "肺與手部之間沒有跳過循環的直接氧氣通道，氧氣仍須由血液運送。", "血液含氧正常仍需實際流到手部，局部無血流會使細胞難以取得氧氣。"], ["區分血液含有氧氣與血液抵達組織兩件事，兩項條件都具備才有正常供氧。", "本題的限制在局部循環，不在肺部交換；因此即使血氧正常，手部仍可能缺氧。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S064", "BIO_R4_S064", "system-coordination-table",
  { title: "踩車前後的呼吸、循環與氣體資料", text: "學生以固定阻力踩健身車六分鐘，研究者在開始前安坐五分鐘，並於踩車最後一分鐘記錄每分鐘呼吸次數、心跳次數、全身氧氣消耗量與二氧化碳排出量。數值為同一名學生的測量結果，氧氣消耗量與二氧化碳排出量的單位皆為毫升／分。", note: "資料只能支持本次活動下的整體變化，不能直接代表每一個細胞的變化幅度。" },
  { summary: "表格比較同一學生安靜與踩車時的呼吸、心跳、氧氣消耗及二氧化碳排出資料。", colorIndependent: true, dataFallback: { columns: ["狀態", "呼吸次數（次／分）", "心跳次數（次／分）", "氧氣消耗量（毫升／分）", "二氧化碳排出量（毫升／分）"], rows: [["安靜", "14", "72", "260", "220"], ["踩車", "31", "138", "1320", "1180"]] } },
  [
    question("BIO_R4_SQ_064_01", "BIO_R4_S064", "standard", "依表中資料，踩車時哪一組變化可直接看出呼吸與循環活動都增強？", ["氧氣消耗與心跳次數都減少", "呼吸次數與心跳次數都增加", "呼吸次數增加但心跳次數不變", "二氧化碳排出量增加但呼吸次數減少"], 1, ["表中氧氣消耗與心跳次數都明顯增加，並沒有同時減少。", "呼吸由十四增至三十一次，心跳由七十二增至一百三十八次，兩者都上升。", "呼吸次數增加時心跳也上升六十六次，不能說心跳維持不變。", "二氧化碳排出量增加的同時呼吸次數也增加，並非一增一減。"], ["直接比較同一欄的安靜值與踩車值，可見呼吸與心跳兩項指標都明顯上升。", "本題只問資料顯示的活動變化，不需由氣體數值推算未直接測量的細胞反應。"]),
    question("BIO_R4_SQ_064_02", "BIO_R4_S064", "advanced", "氧氣消耗量與二氧化碳排出量在踩車時都大幅增加，最合理的解釋為何？", ["肺部停止交換氣體，所以氣體留在血液中", "小腸在六分鐘內製造大量氧氣供肌肉使用", "活動肌肉細胞釋能增加，需要較多氧氣並產生較多二氧化碳", "心臟直接分解養分並供應所有肌肉能量"], 2, ["若肺部停止交換，便難以同時出現較高的氧氣消耗與二氧化碳排出量。", "小腸負責消化與吸收養分，不會製造大量氧氣供應運動中的肌肉。", "踩車使肌肉能量需求增加，細胞呼吸增強可解釋氧氣消耗和二氧化碳產生上升。", "心臟負責推動血液，肌肉所用能量仍由各肌肉細胞的代謝反應釋放。"], ["把兩項氣體視為細胞呼吸的反應物與產物，可由同步上升推論整體釋能活動增強。", "呼吸與心跳加快負責交換和運送，不能誤說肺或心臟替全身細胞直接製造能量。"]),
    question("BIO_R4_SQ_064_03", "BIO_R4_S064", "transfer", "另一學生踩相同阻力時呼吸次數同樣為三十一次，但心跳僅八十次。若要判斷其肌肉供氧是否相同，最適合再測哪項資料？", ["兩人的身高與座號", "健身車外殼的顏色", "當天教室牆面的溫度", "流向腿部的血流量與血液含氧量"], 3, ["身高可能影響體型差異，但不能直接顯示氧氣是否隨血液送達腿部肌肉。", "器材外殼顏色不參與呼吸、循環或氧氣運送，不能判定肌肉供氧。", "牆面溫度不是學生局部氧氣運送的直接指標，無法回答供氧是否相同。", "局部血流量配合血液含氧量，可直接評估氧氣經循環送到腿部的情形。"], ["呼吸次數相同不代表循環送氧相同，還要檢查血液含氧及實際流向活動肌肉的量。", "題目要比較肌肉供氧，應補測最接近氧氣運輸結果的資料，而非與生理流程無關的背景項目。"]),
  ],
));

questions.find(q => q.id === "BIO_R4_Q_057_01").reasons[2] = "小腸位於消化道後段，食物會通過此處而空氣不會經過。";
questions.find(q => q.id === "BIO_R4_Q_057_01").reasons[3] = "膀胱只暫時儲存尿液，與吸入空氣進入肺部的路徑無關。";
questions.find(q => q.id === "BIO_R4_Q_057_02").reasons[2] = "胃屬於消化道，既不直接連接呼吸道，也不負責輸送空氣。";
questions.find(q => q.id === "BIO_R4_Q_057_02").reasons[3] = "大腸位於消化道末段，不會出現在鼻腔通往肺部的空氣路徑。";
questions.find(q => q.id === "BIO_R4_Q_057_02").reviews[0] = "由鼻腔依序經過咽與喉之後，吸入的空氣下一段會進入氣管。";
questions.find(q => q.id === "BIO_R4_Q_057_03").reasons[1] = "食道是食物通往胃的管道，不會由氣管分叉形成兩條支氣管。";
questions.find(q => q.id === "BIO_R4_Q_057_03").reasons[3] = "膽管負責把膽汁運送到小腸，並不是空氣進入左右肺的分支。";
questions.find(q => q.id === "BIO_R4_Q_057_04").reasons[1] = "此排列由肺部朝鼻腔前進，較接近呼氣方向而不是吸氣方向。";
questions.find(q => q.id === "BIO_R4_Q_057_04").reasons[2] = "大腸、小腸與胃都屬於消化道，無法構成吸入空氣的通路。";
questions.find(q => q.id === "BIO_R4_Q_057_05").reasons[1] = "鼻腔是常見吸氣入口，屬於正常空氣通過路徑。";
questions.find(q => q.id === "BIO_R4_Q_057_05").reasons[2] = "氣管負責把吸入空氣送向胸腔與支氣管。";
questions.find(q => q.id === "BIO_R4_Q_057_06").reasons[2] = "小腸絨毛負責增加養分吸收面積，並不參與空氣進出肺部。";
questions.find(q => q.id === "BIO_R4_Q_057_06").reasons[3] = "胃腺分泌胃液進行消化，沒有把空氣送入肺泡的呼吸功能。";
questions.find(q => q.id === "BIO_R4_Q_057_07").reasons[0] = "小腸運送並消化食物，管腔並未與肺泡形成正常空氣通路。";
questions.find(q => q.id === "BIO_R4_Q_057_07").reasons[1] = "食道把食團送往胃部，不屬於鼻腔到肺部之間的呼吸道。";
questions.find(q => q.id === "BIO_R4_Q_057_08").reasons[2] = "肝臟與膽囊屬消化相關器官，不是氣管進入肺後的分支。";
questions.find(q => q.id === "BIO_R4_Q_057_10").reasons[2] = "食道通往胃部而不是肺部，因此無法直接把吸入空氣送到肺泡。";
questions.find(q => q.id === "BIO_R4_Q_057_10").reasons[3] = "支氣管運送空氣進肺，既不運送食團也不連接小腸。";
questions.find(q => q.id === "BIO_R4_Q_057_11").reasons[1] = "食道只把食物送往胃部，正常情況下不會通往肺泡進行換氣。";
questions.find(q => q.id === "BIO_R4_Q_057_12").reasons[1] = "尿液由輸尿管進入膀胱，這條泌尿路徑不會運送吸入空氣。";
questions.find(q => q.id === "BIO_R4_Q_057_12").reasons[2] = "膽汁經膽管進入小腸協助消化脂質，並非呼吸氣體的通路。";
questions.find(q => q.id === "BIO_R4_Q_058_03").reasons[0] = "切碎食物由牙齒負責，不能解釋肺泡薄壁如何促進氣體交換。";
questions.find(q => q.id === "BIO_R4_Q_058_03").reasons[1] = "尿液經輸尿管運送到膀胱，與肺泡氣體擴散功能沒有關聯。";
questions.find(q => q.id === "BIO_R4_Q_058_03").reasons[3] = "膽汁由肝臟製造以協助脂質消化，不能說明肺泡交換氣體。";
questions.find(q => q.id === "BIO_R4_Q_058_08").reasons[1] = "題幹沒有提供壁厚差異，不能把交換量差異歸因於此項條件。";
questions.find(q => q.id === "BIO_R4_Q_058_08").reasons[2] = "肺泡本身不會製造血管，微血管密布是既有的交換構造特徵。";
questions.find(q => q.id === "BIO_R4_Q_058_10").reasons[2] = "鼻毛主要攔截較大顆粒，不能取代肺泡薄壁所縮短的擴散距離。";
questions.find(q => q.id === "BIO_R4_Q_058_12").reasons[0] = "肺泡壁很薄只能縮短擴散距離，並不表示氣體移動距離等於零。";
questions.find(q => q.id === "BIO_R4_Q_059_02").reasons[2] = "胃負責消化食物，不會與肺泡之間形成氧氣濃度差並交換氧氣。";
questions.find(q => q.id === "BIO_R4_Q_059_03").reasons[3] = "膀胱只儲存尿液，既沒有肺泡結構，也不參與氧氣擴散。";
questions.find(q => q.id === "BIO_R4_Q_059_05").reasons[2] = "食道不在肺泡與微血管的交換界面，不能決定氧氣擴散方向。";
questions.find(q => q.id === "BIO_R4_Q_059_06").reasons[3] = "兩側存在濃度差時仍會有淨擴散，不能判定氣體完全沒有移動。";
questions.find(q => q.id === "BIO_R4_Q_059_08").reasons[2] = "氧分子始終保持隨機運動，只是整體淨移動方向由濃度差決定。";
questions.find(q => q.id === "BIO_R4_Q_060_02").reasons[2] = "細胞呼吸發生在細胞內，並非胸腔容積改變造成的肺部換氣。";
questions.find(q => q.id === "BIO_R4_Q_060_02").reasons[3] = "排遺是排出未消化食物殘餘，與空氣進出肺部的換氣不同。";
questions.find(q => q.id === "BIO_R4_Q_060_04").reasons[1] = "胃腔主要處理食物，並不是肺泡氣體和血液互換的場所。";
questions.find(q => q.id === "BIO_R4_Q_060_09").reasons[2] = "題示障礙位於細胞利用階段，胸腔通氣仍可能正常。";
questions.find(q => q.id === "BIO_R4_Q_060_10").reasons[2] = "肺泡不負責製造葡萄糖，只負責讓氧氣與二氧化碳跨膜交換。";
questions.find(q => q.id === "BIO_R4_Q_061_05").reasons[3] = "糞便形成屬於消化道排遺，並不是細胞呼吸利用養分的產物。";
questions.find(q => q.id === "BIO_R4_Q_062_02").reasons[2] = "氮氣比例在吸入與呼出氣中通常變化較小，並非明顯增加的氣體。";
questions.find(q => q.id === "BIO_R4_Q_062_04").reasons[1] = "氮氣仍是呼出氣的重要成分，不能因氧氣下降就推論氮氣消失。";
questions.find(q => q.id === "BIO_R4_Q_062_05").reasons[3] = "題目資料沒有顯示氮氣消失，反而顯示呼出氣仍含大量氮氣。";
questions.find(q => q.id === "BIO_R4_Q_062_07").reasons[0] = "呼氣形成水霧只能顯示含有水氣，不能證明呼出氣完全沒有氧氣。";
questions.find(q => q.id === "BIO_R4_Q_062_10").reasons[2] = "乾燥處理只改變水氣含量，不會把肺或其他器官的種類改變。";
questions.find(q => q.id === "BIO_R4_Q_063_02").reasons[3] = "肺泡面積屬於構造資料，不能直接代表每分鐘呼吸次數的測量值。";
questions.find(q => q.id === "BIO_R4_Q_063_07").reasons[0] = "肺部不會製造葡萄糖，運動時養分來源仍須由消化吸收與儲存供給。";
questions.find(q => q.id === "BIO_R4_Q_063_10").reasons[2] = "主觀感覺缺少一致的量化標準，不適合取代呼吸次數等客觀數據。";
questions.find(q => q.id === "BIO_R4_Q_063_11").reasons[0] = "肺部不進行澱粉化學消化，呼吸加快不能用消化澱粉來解釋。";
stimuli.find(s => s.id === "BIO_R4_ST_S057").questions.find(q => q.id === "BIO_R4_SQ_057_01").reasons[2] = "胃屬於消化道而非呼吸道，不會出現在空氣進入肺部的順序中。";
stimuli.find(s => s.id === "BIO_R4_ST_S057").questions.find(q => q.id === "BIO_R4_SQ_057_02").reasons[2] = "氣管是運送空氣的管道，不是主要氣體交換界面。";
stimuli.find(s => s.id === "BIO_R4_ST_S058").questions.find(q => q.id === "BIO_R4_SQ_058_01").reasons[1] = "甲膜較厚且乾燥、液體又不流動，三項條件都不利於擴散交換。";
stimuli.find(s => s.id === "BIO_R4_ST_S058").questions.find(q => q.id === "BIO_R4_SQ_058_02").reasons[1] = "乙與丙都使用薄而濕潤的膜，不能解釋兩組交換速率的差異。";
stimuli.find(s => s.id === "BIO_R4_ST_S058").questions.find(q => q.id === "BIO_R4_SQ_058_03").reasons[2] = "裝置外殼顏色不是氣體交換條件，不會改變膜兩側的擴散速率。";
stimuli.find(s => s.id === "BIO_R4_ST_S059").questions.find(q => q.id === "BIO_R4_SQ_059_01").reasons[3] = "表中膜兩側氧氣數值明顯不同，並不符合兩側濃度完全相等。";
stimuli.find(s => s.id === "BIO_R4_ST_S059").questions.find(q => q.id === "BIO_R4_SQ_059_01").reviews[1] = "肺泡氧濃度高於血液，因此氧氣由肺泡向血液產生淨擴散。";
stimuli.find(s => s.id === "BIO_R4_ST_S059").questions.find(q => q.id === "BIO_R4_SQ_059_03").reasons[3] = "擴散只改變氧氣所在位置，不會把氧分子直接轉變成水分子。";
stimuli.find(s => s.id === "BIO_R4_ST_S060").questions.find(q => q.id === "BIO_R4_SQ_060_01").reasons[0] = "甲只描述空氣進出，沒有描述氣體跨越肺泡壁進入或離開血液。";
stimuli.find(s => s.id === "BIO_R4_ST_S060").questions.find(q => q.id === "BIO_R4_SQ_060_01").reasons[3] = "養分吸收主要發生在小腸，與圖示胸腔換氣機制並不相同。";
stimuli.find(s => s.id === "BIO_R4_ST_S061").questions.find(q => q.id === "BIO_R4_SQ_061_01").reasons[2] = "二氧化碳由三增加到十，數值變化方向與題述下降不一致。";
stimuli.find(s => s.id === "BIO_R4_ST_S061").questions.find(q => q.id === "BIO_R4_SQ_061_01").reasons[3] = "能量指標由四升到十三，資料不支持能量供應降低的說法。";
stimuli.find(s => s.id === "BIO_R4_ST_S062").questions.find(q => q.id === "BIO_R4_SQ_062_01").reasons[0] = "二氧化碳比例上升而氮氣也未下降，並非兩種氣體都減少。";
stimuli.find(s => s.id === "BIO_R4_ST_S062").questions.find(q => q.id === "BIO_R4_SQ_062_02").reasons[2] = "氮氣雖占百分之七十九，仍不是呼出氣的全部成分，另含氧與二氧化碳。";
stimuli.find(s => s.id === "BIO_R4_ST_S062").questions.find(q => q.id === "BIO_R4_SQ_062_03").reasons[2] = "呼出氣原本就會保留一部分氧氣，因此不能僅由含氧判定測量錯誤。";
stimuli.find(s => s.id === "BIO_R4_ST_S062").questions.find(q => q.id === "BIO_R4_SQ_062_03").reasons[3] = "百分之十七明顯不等於零，不能宣稱樣本完全不含氧氣。";
stimuli.find(s => s.id === "BIO_R4_ST_S063").questions.find(q => q.id === "BIO_R4_SQ_063_01").reasons[1] = "休息時每分鐘換氣量只有六公升，遠低於運動時的三十六公升。";
stimuli.find(s => s.id === "BIO_R4_ST_S063").questions.find(q => q.id === "BIO_R4_SQ_063_02").reasons[0] = "恢復期數值逐步下降而沒有持續增加，因此不符合一路升高的說法。";
stimuli.find(s => s.id === "BIO_R4_ST_S063").questions.find(q => q.id === "BIO_R4_SQ_063_02").reasons[2] = "停止運動後仍持續呼吸，資料只能顯示換氣量逐漸接近休息值。";

